object SubscribeHelper {

    @Composable
    fun periodTitle(
        period: SubscriptionPeriod,
        isReview: Boolean = true,
        annual12MonthsText: Boolean
    ) = when (period) {
        SubscriptionPeriod.WEEK -> stringResource(if (isReview) Res.string.onboarding_propose_subscription_week else Res.string.paywall_box_buttons_weekly)
        SubscriptionPeriod.MONTH -> if (annual12MonthsText) "1 ${stringResource(Res.string.onboarding_propose_subscription_month)}"
        else stringResource(if (isReview) Res.string.onboarding_propose_subscription_month else Res.string.paywall_box_buttons_monthly)
        SubscriptionPeriod.THREE_MONTH -> if (annual12MonthsText) "3 ${stringResource(Res.string.onboarding_propose_subscription_months)}"
        else stringResource(if (isReview) Res.string.onboarding_propose_subscription_three_months else Res.string.paywall_box_buttons_quarterly)
        SubscriptionPeriod.SIX_MONTH -> "6 ${stringResource(Res.string.onboarding_propose_subscription_months)}"
        SubscriptionPeriod.YEAR ->
            if (annual12MonthsText) "12 ${stringResource(Res.string.onboarding_propose_subscription_months)}"
            else if (isReview) stringResource(Res.string.onboarding_propose_subscription_year)
            else stringResource(Res.string.paywall_box_buttons_yearly)
    }

    @Composable
    fun getGradient(
        onSelected: Boolean,
        isUnlim: Boolean = true,
        isNewHorizontalDesign: Boolean = false
    ) = Brush.linearGradient(
        gradientColors(onSelected, isUnlim, isNewHorizontalDesign),
        start = Offset(0f, Float.POSITIVE_INFINITY),
        end = Offset(Float.POSITIVE_INFINITY, 0f)
    )

    @Composable
    fun gradientColors(
        onSelected: Boolean,
        isUnlim: Boolean = true,
        isNewHorizontalDesign: Boolean = false
    ) = if (onSelected) {
        if (isUnlim) listOf(
            MainTheme.colors.gradient_subscribe_unlim_color_start,
            MainTheme.colors.gradient_subscribe_unlim_color_end
        ) else listOf(
            MainTheme.colors.gradient_subscribe_plus_color_start,
            MainTheme.colors.gradient_subscribe_plus_color_end
        )
    } else {
        if (isNewHorizontalDesign) listOf(Color(0xFF1F1F26), Color(0xFF1F1F26))
        else listOf(
            MainTheme.colors.btn_subscribe_unselect_color,
            MainTheme.colors.btn_subscribe_unselect_color
        )
    }

    @Composable
    fun borderColor(isUnlim: Boolean) =
        if (isUnlim) MainTheme.colors.gradient_subscribe_unlim_color_end
        else MainTheme.colors.gradient_subscribe_plus_color_end

    fun buySubscription(
        productDetails: ProductDetails,
        selectedProductID: MutableState<String>,
        btnProgress: MutableState<Boolean>,
        isBottomDrawerFragment: Boolean = false,
        buySubscription: (Billings, Boolean, Boolean) -> Unit,
    ) {
        val productId = productDetails.productDetails.productId
        if (selectedProductID.value == productId) {
            btnProgress.value = true
            val buyProductId = productDetails.discountDetails?.productId ?: productId
            Billings.getBillingByProductId(buyProductId)
                ?.let { billing ->
                    buySubscription.invoke(billing, true, isBottomDrawerFragment)
                }
        } else {
            selectedProductID.value = productId
            val buyProductId = productDetails.discountDetails?.productId ?: productId
            Billings.getBillingByProductId(buyProductId)?.let { billing ->
                buySubscription.invoke(billing, false, isBottomDrawerFragment)
            }
        }
    }
}


@Composable
fun getTextPriceComposeNew(
    productDetails: PurchaseInfo,
    discountDetails: PurchaseInfo?,
    startPrice: Double,
    isWeekFormat: Boolean
): TextPricesAndPercent {
    var currentPrice = ""
    var currentPriceDiscount = ""
    var currencyPercentDiscountFormat = ""
    val billingManager by di.instance<IBillingManager>()
    val skuDetails =
        billingManager.getSubscribePrice(productDetails.productId) ?: return TextPricesAndPercent()
    val priceCurrentCode = skuDetails.priceCurrencyCode
    val price = skuDetails.priceAmountMicros / 1000000.0
    var discountPrice = price
    val introductoryPrice =
        billingManager.getSubscribePrice(discountDetails?.productId)
            ?.let { it.priceAmountMicros / 1000000.0 }
            ?: 0.0
    if (introductoryPrice == 0.0) {
        val priceFormat = getPriceFormat(price)
        val priceString = "$priceCurrentCode $priceFormat"
        currentPrice = priceString
    } else {
        discountPrice = introductoryPrice

        val priceFormat = getPriceFormat(price, true)
        val introductoryFormat = getPriceFormat(introductoryPrice, true)

        val currencyPercentDiscount = (price - introductoryPrice) * 100 / price
        currencyPercentDiscountFormat = getPriceFormat(
            currencyPercentDiscount,
            percentFormat = true
        )

        currentPriceDiscount = "$priceCurrentCode $introductoryFormat"
        currentPrice = "$priceCurrentCode $priceFormat"
    }

    val monthFormat = stringResource(
        resource =
        if (isWeekFormat) Res.string.subscribe_settings_weekly_text
        else Res.string.subscribe_settings_month_text
    ).lowercase()

    val discountValue = getProductWeekPrice(productDetails, discountPrice, isWeekFormat)
    val discountText =
        getPriceFormat(discountValue, changeFormat = introductoryPrice != 0.0)
    var discountPercent = (startPrice - discountValue) * 100 / startPrice
    if (discountPercent % 5 >= 1) discountPercent += 5 - discountPercent % 5
    var textPercent = discountPercent.toInt()
    if (textPercent <= 0) textPercent = 0

    return TextPricesAndPercent(
        currentPrice,
        "$priceCurrentCode $discountText  $monthFormat",
        "$priceCurrentCode $discountText",
        currentPriceDiscount,
        currencyPercentDiscountFormat,
        price, discountPrice,
        textPercent
    )
}

fun getPriceFormat(
    price: Double,
    changeFormat: Boolean = false,
    percentFormat: Boolean = false
): String {
    return if (price >= 10000 || percentFormat) {
        price.toInt().toString()
    } else if (changeFormat && price >= 1000) {
        price.toInt().toString()
    } else {
        price.toString(2)
    }
}

fun Double.toString(numOfDec: Int): String {
    val integerPart = this.toInt()

    if (numOfDec > 0) {
        val decimalPart = this - integerPart
        val decimalAsIntValue = (decimalPart * (10 * numOfDec)).roundToInt()
        if (decimalAsIntValue == 0) return "$integerPart.00"
        return "$integerPart.$decimalAsIntValue"
    } else {
        return integerPart.toString()
    }
}

fun getProductWeekPrice(
    productDetails: PurchaseInfo,
    price: Double,
    isWeekFormat: Boolean
): Double {
    var weekPrice = if (isWeekFormat) {
        when {
            Billings.isMonthSubscribe(productDetails.productId) -> (price / 30) * 7
            Billings.is3MonthsSubscribe(productDetails.productId) -> (price / (30 * 3)) * 7
            Billings.is6MonthsSubscribe(productDetails.productId) -> (price / (30 * 6)) * 7
            Billings.isYearSubscribe(productDetails.productId) -> (price / (365)) * 7
            else -> price
        }
    } else {
        when {
            Billings.is3MonthsSubscribe(productDetails.productId) -> price / 3
            Billings.is6MonthsSubscribe(productDetails.productId) -> price / 6
            Billings.isYearSubscribe(productDetails.productId) -> price / 12
            else -> price
        }
    }

    val extraAmount = weekPrice % 1.0
    if (extraAmount >= 0.991) {
        val extra = weekPrice % 0.01
        weekPrice -= extra
    } else if (extraAmount <= 0.1) {
        val extra = (weekPrice % 0.1) + 0.01
        weekPrice -= extra
    }
    return weekPrice
}


data class TextPricesAndPercent(
    val textPricePeriod: String = "",
    val textDefaultPricePeriod: String = "",
    val textDefaultPriceWeek: String = "",
    val textPriceDiscountPeriod: String = "",
    val textPercentDiscount: String = "",
    val productPrice: Double = 0.0,
    val defaultProductPrice: Double = 0.0,
    val textPercent: Int = 0
)