@Composable
fun ProfilePhotoCropScreenJs(
    image: String,
    onBack: () -> Unit,
    cropPhoto: (String) -> Unit
) {

    val rotation = remember { mutableStateOf(0.0) } // 0, 90, 180, 270
    val minZoom = remember { mutableStateOf(1f) }
    val zoomLevel = remember { mutableStateOf(1f) }
    val shouldCrop = remember { mutableStateOf(false) }
    var cropResult = ""

    PageColumnContainer {
        JsCropImageTabBar(
            showRotateButton = true,
            rotate = { rotation.value = (rotation.value + 90) },
            onBack = { onBack.invoke() }
        )

        Box(
            Modifier.fillMaxWidth()
                .position(Position.Relative)
                .weight(1)
        ) {
            CropImageContentJs(
                imageUrl = image,
                zoom = zoomLevel.value,
                rotation = rotation.value.toInt(),
                onMinZoomCalculated = { calculatedMin ->
                    minZoom.value = calculatedMin
                    if (zoomLevel.value < calculatedMin) zoomLevel.value = calculatedMin
                },
                shouldCrop = shouldCrop.value,
                onCropResult = {
                    cropResult = it
                    cropPhoto.invoke(cropResult)
                    shouldCrop.value = false
                }
            )

            ZoomControlPanelJs(
                modifier = Modifier.align(Alignment.BottomCenter)
                    .position(Position.Absolute),
                minZoom = minZoom.value,
                zoomLevel = zoomLevel.value,
                onZoomChange = {
                    zoomLevel.value = it
                }
            )
        }

        val colors = listOf(
            JsMainTheme.colors.gradient_subscribe_unlim_color_start,
            JsMainTheme.colors.gradient_subscribe_unlim_color_end
        )

        val buttonTitle = stringResource(Res.string.people_profile_download_photo_title)
        JsMainButtonCustom(
            text = buttonTitle,
            colors = colors
        ) {
            shouldCrop.value = true
        }
    }
}

@Composable
private fun JsCropImageTabBar(
    showRotateButton: Boolean,
    rotate: () -> Unit,
    onBack: () -> Unit,
) {
    Column(Modifier.fillMaxWidth()) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .height(56.dp)
            /*.background(JsMainTheme.colors.main_color_header)*/,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Box(Modifier.padding(left = 16.dp)) {
                Box(
                    Modifier
                        .size(36.dp)
                        .clipByCorner(18)
                        .alignCenter()
                        .background(Color.rgb(0X282B30))
                        .clickable { onBack() }
                ) {
                    JsImageView(
                        Res.drawable.ic_back_arrow/*"ic_back_arrow_web"*/,
                        Modifier.size(16.dp)
                    )
                }
            }

            JsTextView(
                text = stringResource(Res.string.onboarding_crop_profile_photo_title),
                textSize = 20,
                modifier = Modifier.padding(left = 24.dp).margin(right = 16.dp)
                    .align(Alignment.CenterVertically),
                textAlign = TextAlign.Center,
                fontWeight = FontWeight.Medium,
            )

            Box(modifier = Modifier.weight(1f))

            if (showRotateButton) {
                JsImageViewTint(
                    drawableId = "ic_rotate_photo",
                    tintColor = JsMainTheme.colors.app_main_color,
                    contentScale = ContentScale.FillWidth,
                    modifier = Modifier.margin(8.px).size(40.px).clickable { rotate.invoke() }
                )
            }
        }

//        JsDividerLine(background = JsMainTheme.colors.main_color_background)
    }
}

@Composable
fun ZoomControlPanelJs(
    modifier: Modifier = Modifier,
    minZoom: Float,
    zoomLevel: Float,
    onZoomChange: (Float) -> Unit,
) {
    Row(
        modifier = modifier.fillMaxWidth().height(42.px),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        JsImageViewTint(
            drawableId = "ic_zoom_minus",
            tintColor = JsMainTheme.colors.app_main_color,
            contentScale = ContentScale.FillWidth,
            modifier = Modifier.margin(16.px).size(30.px)
        )

        Input(
            type = InputType.Range,
            attrs = {
                min("$minZoom")
                max("${minZoom + 2.5}")
                step(0.01)
                value(zoomLevel.toString())

                // Обработка изменений
                onInput { event ->
                    val value = event.value?.toFloat() ?: 1f
                    onZoomChange(value)
                }

                // Стилизация самого инпута
                style {
                    width(100.percent)
                    cursor("pointer")
                    // Можно добавить accent-color для современных браузеров
                    property("accent-color", "white")
                }
            }
        )
        JsImageViewTint(
            drawableId = "ic_zoom_plus",
            tintColor = JsMainTheme.colors.app_main_color,
            contentScale = ContentScale.FillWidth,
            modifier = Modifier.margin(16.px).size(30.px)
        )
    }
}

