        modifier = Modifier.fillMaxWidth().margin(leftRight = 16.dp)
            .aspectRatio(1 / 1.2)
    ) {
        AsyncImageJs(
            src = cropResult,
            modifier = Modifier.fillMaxSize(),
            onSuccess = {

            }
        )
    }
}
