object IndexedDbStorage {

    val dbName = {
        var databaseName = if (AppVariant.isFiorry()) "FiorryWebDb"
        else if (AppVariant.isElizium()) "EliziumWebDb"
        else if (AppVariant.isHeaven()) "HeavenWebDb"
        else if (AppVariant.isParadiz()) "ParadizWebDb"
        else "DreamTekWebDb"
        if (AppVariant.isDev()) databaseName = "Stage$databaseName"
        databaseName
    }

    suspend inline fun <reified T> saveAllItems(
        storeName: StoreName,
        items: List<T>?
    ): Boolean {
        items?.forEach { item ->
            val result = saveItem(storeName, json)
            if (!result) return false
        }
        return true
    }

    suspend inline fun <reified T> saveItem(storeName: StoreName, item: T?): Boolean {
        val jsonString = JsonObjectConverter.objectToString(item) ?: return true
        val jsObject = DatabaseInterop.parseJson(jsonString)
        val result = DatabaseInterop.saveItem(dbName(), storeName.name, jsObject).await()
        return result
    }

    suspend inline fun <reified T> getAllItems(storeName: StoreName): List<T> {
        val result = DatabaseInterop.getAllItems(dbName(), storeName.name).await()
        return result.mapNotNull {
            try {
                val jsonString = DatabaseInterop.toJson(it)
                val myJsonObject = JsonObjectConverter.stringToObject<T>(jsonString)
                myJsonObject
            } catch (_: Throwable) {
                null
            }
        }
    }

    suspend inline fun <reified T> getItemById(storeName: StoreName, id: String): T? {
        if (id.isEmpty()) return null
        val all = getAllItems<T>(storeName)
        return all.find { (it as? WithId)?.id == id }
    }

    suspend fun getItemByLogin(storeName: StoreName, login: String): Account? {
        if (login.isEmpty()) return null
        val all = getAllItems<Account?>(storeName)
        val account = all.find { it?.login == login }
        return account
    }

    suspend fun deleteItem(storeName: StoreName, id: String) {
        DatabaseInterop.deleteItem(dbName(), storeName.name, id).await()
    }

    suspend fun deleteDatabase() {
        DatabaseInterop.deleteDb(dbName()).await()
    }
}

enum class StoreName {
    accounts, chats, wows, notifications
}
