package web.screens.onboarding.paywall.views

import androidx.compose.runtime.Composable
import com.varabyte.kobweb.compose.foundation.layout.Box
import com.varabyte.kobweb.compose.ui.Modifier
import com.varabyte.kobweb.compose.ui.graphics.Color
import com.varabyte.kobweb.compose.ui.modifiers.background
import com.varabyte.kobweb.compose.ui.modifiers.border
import com.varabyte.kobweb.compose.ui.modifiers.fillMaxSize
import com.varabyte.kobweb.compose.ui.modifiers.padding
import org.jetbrains.compose.web.css.LineStyle
import web.helpers.clipByCorner
import web.helpers.dp
import web.helpers.gradientBackground
import web.screens.onboarding.paywall.JsSubscribeHelper
import web.theme.JsMainTheme


@Composable
fun SubscriptionButtonBackground(
    isNewHorizontalDesign: Boolean,
    isNewDesign: Boolean,
    isUnlim: Boolean,
    onSelected: Boolean,
) {
    val gradient = JsSubscribeHelper.gradientColors(onSelected, isUnlim, isNewHorizontalDesign)

    when {
        isNewHorizontalDesign -> SubscribeButtonBackgroundNewHorizontalDesign(gradient)
        isNewDesign -> SubscriptionButtonBackgroundNewDesign(onSelected, gradient)
        else -> SubscriptionButtonBackgroundDefault(
            onSelected,
            JsSubscribeHelper.borderColor(isUnlim),
            gradient
        )
    }
}

@Composable
fun SubscriptionButtonBackgroundDefault(
    onSelected: Boolean,
    borderColor: Color,
    gradient: List<Color>
) {
    if (!onSelected) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .clipByCorner()
                .border(2.dp, style = LineStyle.Solid, borderColor)
        )
    } else {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .clipByCorner()
                .gradientBackground(gradient)
        )
    }
}

@Composable
fun SubscriptionButtonBackgroundNewDesign(
    onSelected: Boolean,
    gradient: List<Color>,
) {
    val borderColors = if (onSelected) gradient else listOf(
        JsMainTheme.colors.btn_subscribe_unselect_color,
        JsMainTheme.colors.btn_subscribe_unselect_color
    )


    Box(
        modifier = Modifier
            .fillMaxSize()
            .clipByCorner()
            .gradientBackground(borderColors)
            .padding(all = 3.dp)
    ) {
        if (onSelected) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(all = 5.dp)
                    .clipByCorner()
                    .background(JsMainTheme.colors.btn_subscribe_unselect_color)
            )
        } else {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .clipByCorner()
                    .background(JsMainTheme.colors.btn_subscribe_unselect_color)
            )
        }
    }
}

@Composable
fun SubscribeButtonBackgroundNewHorizontalDesign(gradient: List<Color>) {
    Box(
        modifier = Modifier
            .fillMaxSize()
            .clipByCorner()
            .gradientBackground(gradient)
            .padding(all = 3.dp)
    ) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .clipByCorner()
                .background(color = Color.rgb(0x1F1F26))
        )
    }
}