package managers

import dependencies.AccountRepository
import dependencies.di
import kotpref.logging.CommonLogger
import kotpref.logging.LogLvl
import kotpref.models.AppVariant
import kotpref.models.paywall.Billings
import kotpref.stores.IAppKeysStorage
import kotpref.utils.IPlatformInfoManager
import org.kodein.di.instance

@Suppress("EXPECT_ACTUAL_CLASSIFIERS_ARE_IN_BETA_WARNING")
actual class AmplitudeManager {

    private val TAG = "AmplitudeManager"
    private val logger = CommonLogger()
    private var lastEvent: AmplitudeEvent? = null

    private val platformInfoManager by di.instance<IPlatformInfoManager>()
    private val accountRepository by di.instance<AccountRepository>()
    private val mixPanelManager by di.instance<MixPanelManager>()

    val apiKey = if (AppVariant.isFiorry()) "aecc658dca785c3a8b287a5d677e88aa"
    else if (AppVariant.isElizium()) "16d5422237b1c9bf82a0d4e71290615a"
    else null

    init {
        if (apiKey != null) {
            init(
                apiKey,
                js(
                    "{ defaultTracking : { " +
                            "sessions: true," +
                            "pageViews: false," +
                            "fileDownloads: false," +
                            "formInteractions: false" +
                            "}," +
                            "flushIntervalMillis: 50000," +
                            "flushQueueSize: 20" +
                            "}"
                )
            )
            val deviceId = platformInfoManager.getDeviceId()
            setDeviceId(deviceId)
            logger.log(LogLvl.DEBUG, TAG, "initAmplitude with deviceId = $deviceId")
            mixPanelManager.init()
        }
    }

    actual fun sendIdentify(event: AmplitudeEvent, value: String) {
        sendIdentify(event.name, value)
    }

    actual fun sendIdentify(key: String, value: String) {
        val identify = Identify()
        identify.set(key, value)
        identify(identify)
        mixPanelManager.sendIdentify(key, value)
        logger.log(LogLvl.DEBUG, TAG, "sendIdentify - key = ${key}, value = $value")

        if (key == "subscription_active" && value == "yes") {
            val appKeys: IAppKeysStorage by di.instance()
            if (!appKeys.sendAmplitudeSubsPurchased) {
                appKeys.sendAmplitudeSubsPurchased = true
                sendIdentify("subscription_purchased", "yes")
            }
        }
    }

    actual fun sendIdentifies(properties: HashMap<String, String>) {
        val identifyObj = Identify()
        properties.forEach { (k, v) ->
            identifyObj.set(k, v)
            logger.log(LogLvl.DEBUG, TAG, "sendIdentify - key = ${k}, value = $v")
        }
        identify(identifyObj)
        mixPanelManager.sendIdentifies(properties)
    }

    actual fun sendEvent(event: AmplitudeEvent) {
        if (apiKey == null) return

        if (lastEvent == event && event !is AmplitudeEvent.SubscriptionShown) return
        lastEvent = event

        fun MutableMap<String, String>.addParams(
            paywallRatingHeader: Boolean?, paywallBoxesButtons: Boolean?,
            paywallWithDarkPrice: Boolean?, paywallType: String?
        ): MutableMap<String, String> {
            if (paywallRatingHeader != null)
                this["3boxes dark paywall"] = if (paywallRatingHeader) "enable" else "disable"
            if (paywallBoxesButtons != null)
                this["3 boxes view"] = if (paywallBoxesButtons) "enable" else "disable"
            if (paywallWithDarkPrice != null)
                this["dark_price"] = if (paywallWithDarkPrice) "enable" else "disable"
            if (paywallType != null) this["2nd push paywall"] = paywallType
            return this
        }

        val params: Map<String, Any?> = when (event) {
            is AmplitudeEvent.SubscriptionShown -> mutableMapOf(
                "purchase_ids" to event.purchaseIds.toString(),
                "source_screen" to event.sourceScreen,
            ).addParams(
                event.paywallRatingHeader,
                event.paywallBoxesButtons,
                event.paywallWithDarkPrice,
                event.paywallType
            )

            is AmplitudeEvent.SubscriptionCloseClicked -> mutableMapOf<String, String>()
                .addParams(
                    event.paywallRatingHeader,
                    event.paywallBoxesButtons,
                    event.paywallWithDarkPrice,
                    event.paywallType
                )

            is AmplitudeEvent.SubscriptionSubscribeClicked -> mutableMapOf(
                "purchase_id" to event.purchaseId,
                "source_screen" to event.sourceScreen,
                "purchase_name" to Billings.getBillingNameByProductId(event.purchaseId)
            ).addParams(
                event.paywallRatingHeader,
                event.paywallBoxesButtons,
                event.paywallWithDarkPrice,
                event.paywallType
            )

            is AmplitudeEvent.SubscriptionPurchased -> mutableMapOf(
                "purchase_id" to event.purchaseId,
                "source_screen" to event.sourceScreen,
                "purchase_name" to Billings.getBillingNameByProductId(event.purchaseId)
            ).addParams(
                event.paywallRatingHeader,
                event.paywallBoxesButtons,
                event.paywallWithDarkPrice,
                event.paywallType
            )

            is AmplitudeEvent.SubscriptionRestored -> mutableMapOf(
                "source_screen" to event.sourceScreen,
            )

            is AmplitudeEvent.SubscriptionError -> mutableMapOf(
                "reason" to event.reason
            ).addParams(
                event.paywallRatingHeader,
                event.paywallBoxesButtons,
                event.paywallWithDarkPrice,
                event.paywallType
            )

            is AmplitudeEvent.GiftProductShown -> mutableMapOf(
                "purchase_ids" to event.purchaseIds.toString(),
                "source_screen" to event.sourceScreen
            )

            is AmplitudeEvent.GiftProductClicked -> mutableMapOf(
                "purchase_id" to event.purchaseId,
                "purchase_name" to Billings.getInAppNameByProductId(event.purchaseId)
            )

            is AmplitudeEvent.GiftProductPurchased -> mutableMapOf(
                "purchase_id" to event.purchaseId,
                "purchase_name" to Billings.getInAppNameByProductId(event.purchaseId)
            )

            is AmplitudeEvent.MessagePackShown -> mutableMapOf(
                "purchase_ids" to event.purchaseIds.toString(),
                "source_screen" to event.sourceScreen
            )

            is AmplitudeEvent.MessagePackClicked -> mutableMapOf(
                "purchase_id" to event.purchaseId,
                "purchase_name" to Billings.getInAppNameByProductId(event.purchaseId)
            )

            is AmplitudeEvent.MessagePackPurchased -> mutableMapOf(
                "purchase_id" to event.purchaseId,
                "purchase_name" to Billings.getInAppNameByProductId(event.purchaseId)
            )

            else -> event.params
        }

        //setDeviceId(platformInfoManager.getDeviceId())
        accountRepository.myAccount?.uuid?.let { setUserId(it) }

        if (params.isEmpty()) {
            track(event.name)
            console.log("Amplitude sendEvent - ${event.name}")
            mixPanelManager.sendEvent(event)
        } else {
            track(event.name, params.toJsObject())
            console.log("Amplitude sendEvent - ${event.name}, params=$params")
            mixPanelManager.sendEvent(event, params)
        }
    }

    private fun Map<String, Any?>.toJsObject(): dynamic {
        val obj = js("{}")
        forEach { (k, v) -> obj[k] = v }
        return obj
    }

}