enum class AmplitudeAccountGender {
    man, trans_woman, trans_man, woman, queer, nonbinary, xdresser;

    companion object {

        fun getGenderByAccountIAmPosition(iam: AccountIam): AmplitudeAccountGender =
            when (iam.position) {
                1 -> trans_woman
                2 -> trans_man
                3 -> woman
                4 -> man
                5 -> xdresser
                6 -> nonbinary
                7 -> queer
                else -> man
            }
    }
}