@Composable
fun JsButtonsMultiSelect(
    itemsFlow: StateFlow<List<MultiSelectItem>>,
    modifier: Modifier = Modifier,
    onClick: (MultiSelectItem) -> Unit
) {
    val itemsState = itemsFlow.collectAsState()
    Column(
        modifier = modifier,
        verticalArrangement = Arrangement.spacedBy(24.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        itemsState.value.forEachIndexed { index, item ->
            if (index > 0 && index % 2 == 0) Spacer(
                Modifier.fillMaxWidth().height(1.dp),
                params = Modifier.fillMaxWidth(70.percent)
                    .background(Color.rgb(0XC9C9C9).copy(0.3f))
            )

            val color = jsBackgroundItemColor(itemsState.value.size, index)
            JsMultiSelectItem(item, color, onClick)
        }
    }
}

@Composable
private fun JsMultiSelectItem(
    item: MultiSelectItem,
    color: Color,
    onClick: (MultiSelectItem) -> Unit
) {
    Box(
        modifier = Modifier
            .fillMaxWidth(70.percent)
            .clipByCorner(30)
            .clickable { onClick.invoke(item) }
            .background(if (item.onSelected) color else JsMainTheme.colors.main_color_background)
            .border(
                2.dp,
                LineStyle.Solid,
                if (item.onSelected) color else color.copy(alpha = 0.5f)
            ),
    ) {
        Box(modifier = Modifier.fillMaxSize()) {
            if (item.onSelected) {
                Box(Modifier.padding(start = 24.dp).align(Alignment.CenterStart)) {
                    JsImageView(
                        Res.drawable.ic_onboarding_select_accept, modifier = Modifier.size(20.dp)
                    )
                }
            }

            JsTextView(
                text = item.itemTitle,
                modifier = Modifier
                    .fillMaxWidth()
                    .align(Alignment.Center)
                    .padding(vertical = 12.dp),
                textColor = JsMainTheme.colors.text_color_default,
                textSize = 15,
                fontWeight = FontWeight.Medium,
                textAlign = TextAlign.Center
            )
        }
    }
}

@Composable
fun jsBackgroundItemColor(size: Int, position: Int): Color = when (position) {
    0 -> if (size > 2) JsMainTheme.colors.bg_color_onboarding_item_1 else JsMainTheme.colors.main_color_item_3
    1 -> if (size > 2) JsMainTheme.colors.bg_color_onboarding_item_2 else JsMainTheme.colors.app_main_color
    2 -> JsMainTheme.colors.bg_color_onboarding_item_3
    3 -> JsMainTheme.colors.bg_color_onboarding_item_4
    4 -> JsMainTheme.colors.bg_color_onboarding_item_5
    5 -> JsMainTheme.colors.bg_color_onboarding_item_6
    6 -> JsMainTheme.colors.bg_color_onboarding_item_7
    else -> JsMainTheme.colors.bg_color_onboarding_item_8

}

@Composable
fun FlowRow(
    modifier: Modifier = Modifier.fillMaxWidth(),
    innerPadding: Int = 0,
    alignment: JustifyContent = JustifyContent.Center,
    content: @Composable (RowScope) -> Unit
) {
    Row(
        modifier = modifier.flexWrap(FlexWrap.Wrap)
            .gap(innerPadding.dp)
            .justifyContent(alignment)
    ) { content(this) }
}