@Composable
fun OnBoardingTransTrialScreen(
    viewModelCallback: (OnBoardingTransTrialEvent) -> Unit,
    viewModel: OnBoardingTransTrialVM = rememberJsViewModel {
        OnBoardingTransTrialVM(viewModelCallback)
    }
) {
    PageContainer {
        Column(
            modifier = Modifier.fillMaxSize(),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            JsCustomTabBar(
                onBack = { viewModel.back() },
                withBackground = false,
                tabBarType = TabBars.EmptyTabBar
            )

            Box(modifier = Modifier.weight(1f).fillMaxWidth()) {
                OnBoardingTransTrialsContent(viewModel)
            }

            Box(modifier = Modifier.height(26.dp))
        }


        StripeByAppleGoogleScreen(
            viewModel,
            onPurchase = { paymentId, priceId, productId ->
                viewModel.showStripeAppleGoogle.value = false
                viewModel.boughtSuccess()
            }, onError = {
                viewModel.dialogManager.showMessageDialog(it)
            }, onClose = {
                viewModel.showStripeAppleGoogle.value = false
            }
        )

        if (viewModel.showingProgress.value) LoadingBlockState()
    }
}

@Composable
fun OnBoardingTransTrialsContent(viewModel: OnBoardingTransTrialVM) {
    Column(
        modifier = Modifier.fillMaxSize(),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Box(modifier = Modifier.fillMaxHeight(0.08f.toPercent()))
        Box(modifier = Modifier.weight(1f))

        JsImageView(
            "ic_trans_trial_logo",
            format = "png",
            modifier = Modifier.fillMaxWidth(20.percent)
        )

        Spacer(modifier = Modifier.height(20.dp))
        JsAutoResizeText(
            text = stringResource(resource = Res.string.onboarding_trans_trial_title),
            modifier = Modifier.fillMaxWidth().padding(horizontal = 24.dp),
            color = JsMainTheme.colors.text_color_default,
            fontWeight = FontWeight.Bold,
            maxTextSize = 22,
            minTextSize = 14,
            textAlign = TextAlign.Center,
            maxLines = 2
        )

        Spacer(modifier = Modifier.height(20.dp))
        JsAutoResizeText(
            text = stringResource(resource = Res.string.onboarding_trans_woman_trial_text),
            modifier = Modifier.fillMaxWidth().padding(horizontal = 48.dp),
            color = JsMainTheme.colors.text_color_default.copy(0.8f),
            maxTextSize = 16,
            minTextSize = 12,
            textAlign = TextAlign.Center,
            maxLines = 2
        )

        Box(modifier = Modifier.weight(1f))

        Spacer(modifier = Modifier.height(30.dp))
        TransModeText()
        Spacer(modifier = Modifier.height(20.dp))
        TryFreeView()
        Spacer(modifier = Modifier.height(20.dp))
        InvisibleModeText()
        Spacer(modifier = Modifier.height(30.dp))
        Box(modifier = Modifier.weight(1f))

        Box(Modifier.fillMaxWidth().height(50.dp), contentAlignment = Alignment.Center) {
            SplashFiorryButton(
                title = stringResource(resource = Res.string.onboarding_trans_trial_activate_btn)
            ) { viewModel.clickedBtn() }
        }

        Spacer(modifier = Modifier.height(20.dp))

        val isWeekFormat = Billings.isWeekSubscribe(viewModel.productId.value)
        val periodFormat = stringResource(
            resource =
                if (isWeekFormat) Res.string.subscribe_settings_weekly_text
                else Res.string.subscribe_settings_month_text
        ).lowercase()

        JsAutoResizeText(
            text = stringResource(
                resource = Res.string.onboarding_trans_trial_activate_price,
                "${viewModel.priceString.value} $periodFormat"
            ),
            modifier = Modifier.fillMaxWidth().padding(horizontal = 24.dp),
            color = Color.rgb(0X687C8B),
            maxTextSize = 10,
            textAlign = TextAlign.Center,
            maxLines = 1
        )

        Spacer(modifier = Modifier.height(20.dp))
        CancelAnytimeStripe()
        Spacer(modifier = Modifier.height(20.dp))

        JsAutoResizeText(
            text = stringResource(resource = Res.string.onboarding_trans_trial_skip_btn),
            modifier = Modifier.fillMaxWidth().padding(horizontal = 24.dp).clickable {
                viewModel.showNextPage()
            },
            color = JsMainTheme.colors.text_color_default,
            maxTextSize = 14,
            minTextSize = 10,
            textAlign = TextAlign.Center,
            textDecoration = TextDecorationLine.Underline
        )
    }
}

@Composable
fun TransModeText() {
    val transMode = stringResource(resource = Res.string.onboarding_trans_trial_mode_title)
    val fullText = stringResource(resource = Res.string.onboarding_trans_trial_mode_text, transMode)

    val transModeModifier = Modifier.styleModifier {
        fontWeight(FontWeight.Bold)
    }

    val transModeStartIndex = fullText.indexOf(transMode)
    val annotatedString = listOf(
        AnnotatedString(fullText.substring(0, transModeStartIndex), null),
        AnnotatedString(
            fullText.substring(transModeStartIndex, transModeStartIndex + transMode.length),
            transModeModifier
        ),
        AnnotatedString(
            fullText.substring(transModeStartIndex + transMode.length),
            null
        ),
    )
    JsAnnotatedStringsText(
        annotatedStrings = annotatedString,
        textSize = 16,
        textColor = JsMainTheme.colors.text_color_default,
        modifier = Modifier.fillMaxWidth().padding(horizontal = 24.dp),
        textAlign = TextAlign.Center
    )
}

