@Composable
fun ProfilePhotosSelectScreen(
    fromPage: PhotosFromPage,
    viewModelCallback: (ProfileSelectPhotosEvent) -> Unit,
    viewModel: ProfileSelectPhotosVM = rememberJsViewModel {
        ProfileSelectPhotosVM(fromPage, viewModelCallback)
    }
) {
    val cameraManager = rememberCameraManager(
        onSuccess = {
            viewModel.pickPhoto = it
            viewModel.showCropPhotoScreen.value = true
        },
        onError = {}
    )

    val galleryManager = rememberGalleryManager(
        onSuccess = {
            viewModel.pickPhoto = it
            viewModel.showCropPhotoScreen.value = true
        },
        onError = {}
    )

    val title = stringResource(
        if (viewModel.userRegistered && fromPage != PhotosFromPage.VerificationDialog) Res.string.onboarding_select_photos_title else Res.string.onboarding_add_photo_title
    )
    val rightButtonTitle =
        if (viewModel.userRegistered && fromPage != PhotosFromPage.VerificationDialog) stringResource(
            Res.string.nav_settings_done
        ) else ""

    PageContainer {
        Column(
            Modifier.fillMaxSize().overflow(Overflow.Hidden),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Box(modifier = Modifier.fillMaxWidth()) {
                JsTabBarWithCenterTitle(
                    title = title,
                    rightButtonTitle = rightButtonTitle,
                    showBackButton = viewModel.userRegistered,
                    withBackground = false,
                    onBack = { /*viewModel.backButtonClick()*/ },
                    rightButtonClick = {
                        if (viewModel.userRegistered && fromPage != PhotosFromPage.VerificationDialog) viewModel.clickedBtn(
                            true
                        )
                    },
                )
            }

            Box(
                modifier = Modifier.fillMaxWidth().weight(1f).padding(top = 16.dp)
                    .position(Position.Relative)
                    .minHeight(0.px)
            ) {
                Box(
                    modifier = Modifier
                        .position(Position.Absolute)
                        .top(0.px)
                        .left(0.px)
                        .right(0.px)
                        .bottom(0.px)
                    // .width(100.percent).height(100.percent) // Тоже можно, но top/bottom надежнее
                ) {
                    DragAndDropGridJs(
                        viewModel,
                        modifier = Modifier.fillMaxSize(),
                        onGalleryClick = { galleryManager.launch() })
                }
            }
            Spacer(modifier = Modifier.minHeight(26.dp))
            SplashFiorryButton(
                title = stringResource(resource = Res.string.onboarding_start_btn_text_next)
            ) { viewModel.clickedBtn(false) }
            Spacer(modifier = Modifier.height(26.dp))
        }
    }

    JsAnimatedVisibility(
        visible = viewModel.showMenuPhotosBottomSheet.value,
        durationMs = 500,
        modifier = Modifier.fillMaxSize().zIndex(5)
    ) {
        Box(
            Modifier.fillMaxSize()
                .background(color = JsMainTheme.colors.main_color_black_transparent_70)
                .clickable { viewModel.onMenuCancelClick() }
                .overflow(Overflow.Hidden)
        ) {
            MenuPhotosBottomSheetJs(
                modifier = Modifier.align(Alignment.BottomCenter),
                onMenuCameraClick = {
                    viewModel.onMenuCancelClick()
                    cameraManager.launch()
                },
                onMenuPhotosClick = {
                    viewModel.onMenuCancelClick()
                    galleryManager.launch()
                },
            ) {
                viewModel.onMenuCancelClick()
            }
        }
    }

    JsAnimatedVisibility(
        visible = viewModel.showCropPhotoScreen.value,
        animationDirection = AnimationDirection.RIGHT_TO_LEFT,
        durationMs = 500
    ) {
        ProfilePhotoCropScreenJs(viewModel.pickPhoto, onBack = {
            viewModel.showCropPhotoScreen.value = false
            viewModel.pickPhoto = ""
        }) {
            CommonLogger().log(LogLvl.DEBUG, "PhotoUrl", "account photo url: $it")
            viewModel.showCropPhotoScreen.value = false
            viewModel.addPhoto(it)
        }
    }
}

suspend fun blobToByteArray(blob: Blob): ByteArray = suspendCancellableCoroutine { continuation ->
    val reader = FileReader()

    reader.onloadend = {
        val buffer = reader.result as? org.khronos.webgl.ArrayBuffer
        if (buffer != null) {

            val byteArray = Int8Array(buffer).unsafeCast<ByteArray>()
            continuation.resume(byteArray)
        } else {
            continuation.resumeWithException(Exception("Failed to convert Blob to ByteArray"))
        }
    }

    reader.onerror = {
        continuation.resumeWithException(Exception("FileReader failed"))
    }

    reader.readAsArrayBuffer(blob)
}