class ProfileDataManager() {
    val appKeys by di.instance<IAppKeysStorage>()
    private val converter = ProfileDataConverter()
    private var isImperial = false

    fun getAccount(): Account? = ProfileDataConverter.account
    fun getUpdateAccount(): Account? = ProfileDataConverter.updateAccount

    fun setMeasurement(isImperial: Int?) {
        this.isImperial = isImperial == 2
    }

    fun setAccount(account: Account?) {
        ProfileDataConverter.account = account
        account?.id?.let {
            ProfileDataConverter.updateAccount =
                Account(it, login = account.login, nickname = account.nickname)
        }
    }

    ///region get data
    suspend fun getProfileData(resId: ProfileDataField): ProfileData {
        val profileData = when (resId) {
            /** Single*/
            ProfileDataField.Pronounce -> converter.getAccountPronounce(resId)
            ProfileDataField.Kids -> converter.getAccountKids(resId)
            ProfileDataField.Figure -> converter.getAccountFigure(resId)
            ProfileDataField.Hair -> converter.getAccountHair(resId)
            ProfileDataField.Eye -> converter.getAccountEye(resId)
            ProfileDataField.Work -> converter.getAccountWork(resId)
            ProfileDataField.Education -> converter.getAccountEducation(resId)
            ProfileDataField.Relationship -> converter.getAccountRelationship(resId)
            ProfileDataField.Accommodation -> converter.getAccountAccommodation(resId)
            ProfileDataField.Sex -> converter.getAccountSex(resId)
            //ProfileDataID.hiv -> converter.getAccountTest(resId)
            //ProfileDataID.stds -> converter.getAccountVeneral(resId)

            /** Date*/
            ProfileDataField.Age -> ProfileData(resId, AccountInfoType.Date)
            //ProfileDataID.last_test -> converter.getAccountLastTest(resId)

            /** Multi Hexagon*/
            ProfileDataField.Iam -> converter.getAccountIam(resId)
            ProfileDataField.Interest -> converter.getAccountInterestedIn(resId)
            ProfileDataField.Looking -> converter.getAccountLookingFor(resId)

            /** Multi*/
            ProfileDataField.Interests -> converter.getAccountInterests(resId)
            ProfileDataField.Music -> converter.getAccountMusic(resId)
            ProfileDataField.Zodiac -> converter.getAccountZodiac(resId)

            /** NumberPicker*/
            ProfileDataField.Height -> ProfileData(resId, AccountInfoType.NumberPicker)
            ProfileDataField.Weight -> ProfileData(resId, AccountInfoType.NumberPicker)

            /** Compatibility */
            ProfileDataField.Compatibility -> ProfileData(
                resId,
                AccountInfoType.Compatibility
            )

            else -> ProfileData(resId)
        }
        profileData.selectData = getContentString(getContentData(resId, selectData = true))
        return profileData
    }

    private fun getContentString(data: Any): String {
        return when (data) {
            is String -> data
            is MutableList<*> -> {
                var result = ""
                data.let {
                    for (i in 0 until it.size) {
                        if (i != 0) result += ", "
                        result += it[i]
                    }
                }
                result
            }

            else -> ""
        }
    }

    suspend fun getContentData(textId: ProfileDataField, selectData: Boolean = false): Any {
        val acc = ProfileDataConverter.account
        var result = when (textId) {
            /** Info text*/
            ProfileDataField.Name -> acc?.nickname
            ProfileDataField.AboutMe -> acc?.info?.about
            ProfileDataField.Age -> {
                val date = DateTimeConverter.stringToDate(acc?.info?.birthday)
                DateTimeConverter.dateToString(date, DateTimeConverter.dateWithMonthNameFormat)
            }

            /** Info single*/
            ProfileDataField.Pronounce ->
                AccountPronounceConverter.positionsToItem(acc?.info?.pronounce).resId().getString()

            ProfileDataField.Work ->
                AccountWorkConverter.positionsToItem(acc?.info?.work).resId().getString()

            ProfileDataField.Education ->
                AccountEducationConverter.positionsToItem(acc?.info?.education).resId().getString()

            ProfileDataField.Accommodation ->
                AccountAccommodationConverter.positionsToItem(acc?.info?.accommodation).resId()
                    .getString()

            ProfileDataField.Relationship ->
                AccountRelationshipStatusConverter.positionsToItem(acc?.info?.relationshipStatus)
                    .resId().getString()

            ProfileDataField.Kids ->
                AccountKidsConverter.positionsToItem(acc?.info?.kids).resId().getString()

            ProfileDataField.Sex ->
                if (AppVariant.isHeaven() || AppVariant.isParadiz()) converter.convertFromSex()
                else AccountSexPositionConverter.positionsToItem(acc?.info?.sexPosition).resId()
                    .getString()

            ProfileDataField.ProfileId -> {
                val profileId = acc?.profileId?.uppercase() ?: ""
                StringBuilder(profileId).insert(profileId.length / 2, "-").toString()
            }

            /** Info multi hexagon*/
            ProfileDataField.Iam -> converter.convertFromIam()
            ProfileDataField.Interest -> converter.convertFromInterest()
            ProfileDataField.Looking -> converter.convertFromLooking()
            ProfileDataField.Zodiac -> converter.convertFromZodiac()

            /** Info multi*/
            ProfileDataField.Interests -> converter.convertFromInterests()
            ProfileDataField.Music -> converter.convertFromMusic()

            /** Parameters*/
            ProfileDataField.Height -> {
                if (selectData) {
                    val height = acc?.info?.height
                    return if (height == null || height.toInt() == 0) ""
                    else height.toString()
                }
                val height = acc?.info?.height?.toInt() ?: return ""
                if (height == 0) return ""
                return if (isImperial) {
                    "${MeasurementConverter.cmToInchConverter(height)} ${Res.string.people_height_inch.getString()}"
                } else "$height ${Res.string.people_height_cm.getString()}"
            }

            ProfileDataField.Weight -> {
                if (selectData) {
                    val weight = acc?.info?.weight
                    return if (weight == null || weight.toInt() == 0) ""
                    else weight.toString()
                }
                val weight = acc?.info?.weight ?: return ""
                if (weight.toInt() == 0) return ""
                return if (isImperial) {
                    val pound = MeasurementConverter.kgToLbConverter(weight)
                    return "$pound ${Res.string.people_weight_pounds.getString()}"
                } else "${weight.toInt()} ${Res.string.people_weight_kg.getString()}"
            }

            ProfileDataField.Figure ->
                AccountFigureTypeConverter.positionsToItem(acc?.info?.figureType).resId()
                    .getString()

            ProfileDataField.Hair ->
                AccountHairColorConverter.positionsToItem(acc?.info?.hairColor).resId().getString()

            ProfileDataField.Eye ->
                AccountEyeColorConverter.positionsToItem(acc?.info?.eyeColor).resId().getString()

            /** Health*/
            /*ProfileDataID.last_test -> {
                if (acc?.info?.hiv != null || acc?.info?.veneral != null || isEdit) {
                    DateTimeConverter.dateStringToMonthWithYearString(acc?.info?.date)
                } else ""
            }
            ProfileDataID.hiv -> {
                var hiv: String? = null
                AccountTest.entries.forEach { if (it.position == acc?.info?.hiv) hiv = it.text }
                hiv
            }
            ProfileDataID.stds -> {
                var stds: String? = null
                AccountVeneral.values()
                    .forEach { if (it.position == acc?.info?.veneral) stds = it.text }
                stds
            }*/
            else -> ""
        } ?: ""
        if (result == AccountEducation.DO_NOT_SHOW.resId().getString()) result = ""
        return result
    }
    ///endregion

    ///region set data
    suspend fun updateAccount(
        textId: ProfileDataField?,
        list: MutableList<String>,
        callback: () -> Unit = {}
    ) {
        var acc: Account = ProfileDataConverter.updateAccount ?: return
        when (textId) {
            /** Info text*/
            ProfileDataField.Name -> acc.nickname = list[0]
            ProfileDataField.AboutMe -> acc.info.about = list[0]
            ProfileDataField.Age -> acc.info.birthday = list[0]

            /** Info single*/
            ProfileDataField.Pronounce -> acc = converter.convertToPronounce(acc, list)
            ProfileDataField.Relationship -> acc =
                converter.convertToRelationship(acc, list)

            ProfileDataField.Kids -> acc = converter.convertToKids(acc, list)
            ProfileDataField.Work -> acc = converter.convertToWork(acc, list)
            ProfileDataField.Education -> acc = converter.convertToEducation(acc, list)
            ProfileDataField.Accommodation -> acc =
                converter.convertToAccommodation(acc, list)

            ProfileDataField.Sex -> acc = converter.convertToPosition(acc, list)

            /** Info multi hexagon*/
            ProfileDataField.Iam ->
                acc.info.iamList = AccountIamConverter.stringToPositions(list)

            ProfileDataField.Interest ->
                acc.info.interestedIn = AccountIamConverter.stringToPositions(list, false)

            ProfileDataField.Looking -> acc.info.lookingFor =
                AccountRelationshipConverter.stringToPositions(list)

            /** Info multi*/
            ProfileDataField.Interests -> acc.info.interests = list
            ProfileDataField.Music -> acc.info.music = list

            /** Parameters*/
            ProfileDataField.Height -> try {
                acc.info.height = list[0].toDouble()
            } catch (_: Throwable) {
            }

            ProfileDataField.Weight -> try {
                acc.info.weight = list[0].toDouble()
            } catch (_: Throwable) {
            }

            ProfileDataField.Figure -> acc = converter.convertToFigure(acc, list)
            ProfileDataField.Hair -> acc = converter.convertToHairColor(acc, list)
            ProfileDataField.Eye -> acc = converter.convertToEyeColor(acc, list)

            /** Health*/
            /*ProfileDataID.last_test -> acc.info.date =
                DateTimeConverter.showStringToDateString(list[0])
            ProfileDataID.hiv -> acc = converter.convertToHiv(acc, list)
            ProfileDataID.stds -> acc = converter.convertToStds(acc, list)*/
            else -> {}
        }
        ProfileDataConverter.account = MergeObjectsUtils.mergeObjects(acc, ProfileDataConverter.account)
        callback()
        ProfileDataConverter.updateAccount = acc
    }

    fun isSetEms(textId: ProfileDataField?): Boolean = when (textId) {
        ProfileDataField.Iam, ProfileDataField.Interest,
        ProfileDataField.Looking, ProfileDataField.Zodiac,
        ProfileDataField.Interests, ProfileDataField.Music -> false

        else -> true
    }

    fun getAboutCategory(): MutableList<ProfileDataField> = ProfileDataModel.getAboutCategory()
    fun getAboutCategoryWithoutTitle(): MutableList<ProfileDataField> = ProfileDataModel.getAboutWithoutTitle()
    fun getParametersCategory(): MutableList<ProfileDataField> = ProfileDataModel.getParametersCategory()
    fun getHealthCategory(): MutableList<ProfileDataField> = ProfileDataModel.getHealthCategory()
    ///endregion
}