package kotpref.models

import kotpref.utils.GeneralConstants

/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 09.11.2022.
 */
class AppVariant {

    companion object {
        var appActive: Boolean = true
        var appVersion: String = ""

        var isFiorry: () -> Boolean = { true }
        var isElizium: () -> Boolean = { false }
        var isHeaven: () -> Boolean = { false }
        var isParadiz: () -> Boolean = { false }

        var isTimeRelease: () -> Boolean = { false }

        var isDev: () -> Boolean = { true }
        var isDebug: () -> Boolean = { true }
        var isReleaseBuild: () -> Boolean = { false }

        var isPlayMarketBuild: () -> Boolean = { isReleaseBuild() && !isDev() }
        var isTestBuild: () -> Boolean = { isDev() && !isReleaseBuild() }

        var isFiorryOrHeaven: () -> Boolean = { isFiorry() || isHeaven() }
        var isEliziumOrParadiz: () -> Boolean = { isElizium() || isParadiz() }

        var isAndroid: () -> Boolean = { false }
        var isIos: () -> Boolean = { false }
        var isWeb: () -> Boolean = { false }

        var isLocalSettings: () -> Boolean = { GeneralConstants.IS_LOCAL && isDebug() }
    }
}