enum class Billings(val value: String) {
    Plus0_7("plus.0_7"), Plus1("plus.1"),
    Plus3("plus.3"), Plus6("plus.6"), Plus12("plus.12"),
    BetaPlus0_7("plus.0_7.beta"), BetaPlus1("plus.1.beta"),
    BetaPlus3("plus.3.beta"), BetaPlus6("plus.6.beta"), BetaPlus12("plus.12.beta"),

    Plus0_7Promo("promo_plus.0_7"),
    Plus1Promo("promo_plus.1"), Plus3Promo("promo_plus.3"), Plus12Promo("promo_plus.12"),

    Plus1Trial("trial_plus.1"), Plus1Trial7("trial_plus.0_7"),
    Plus0Trial3("trial_plus.0_3"),

    Unlim0_7("unlimited.0_7"), Unlim1("unlimited.1"), Unlim3("unlimited.3"),
    Unlim6("unlimited.6"), Unlim12("unlimited.12"),
    BetaUnlim0_7("unlimited.0_7.beta"), BetaUnlim1("unlimited.1.beta"),
    BetaUnlim3("unlimited.3.beta"), BetaUnlim6("unlimited.6.beta"), BetaUnlim12("unlimited.12.beta"),

    Unlim0_7Promo("promo_unlimited.0_7"),
    Unlim1Promo("promo_unlimited.1"), Unlim3Promo("promo_unlimited.3"),
    Unlim12Promo("promo_unlimited.12"),

    Unlim12Discount("discount_unlimited.12"), BetaUnlim12Discount("discount_unlimited.12.beta"),
    MaxUnlim12Discount("discount_unlimited.12.max"), MinUnlim12Discount("discount_unlimited.12.min"),

    Unlim12Trial("trial_unlimited.12"), Unlim1Trial("trial_unlimited.1"), Unlim0Trial7("trial_unlimited.0_7"),
    BetaUnlim12DiscountTrial("trial_discount_unlimited.7_12.beta"), Unlim7Trial7("trial_unlimited.7_7"),

    GiftBronze("gift.bronze"), GiftSilver("gift.silver"),
    GiftGold("gift.gold"), GiftPlatinum("gift.platinum"),


    MessagePack5("msg_pack.5"), MessagePack10("msg_pack.10"),
    MessagePack20("msg_pack.20"), MessagePack50("msg_pack.50"),
    MessagePack100("msg_pack.100"), MessagePack500("msg_pack.500"),
    ;


    fun getSubscribe(): String {
        if (value.isEmpty()) return ""
        val suffix = if (AppVariant.isDev()) ".dev" else ""
        return "$prefix$value$suffix"
    }

    companion object {
        val prefix = when {
            AppVariant.isElizium() -> "kd."
            AppVariant.isHeaven() -> "hv."
            AppVariant.isParadiz() -> "pr."
            else -> ""
        }

        private val weekSubscribeList = mutableListOf(
            Plus0_7.getSubscribe(), Unlim0_7.getSubscribe(),
            BetaPlus0_7.getSubscribe(), BetaUnlim0_7.getSubscribe(),
            Plus0_7Promo.getSubscribe(), Unlim0_7Promo.getSubscribe(),
            Plus0Trial3.getSubscribe(), Unlim0Trial7.getSubscribe(),
            Unlim7Trial7.getSubscribe()
        )

        private val monthSubscribeList = mutableListOf(
            Plus1.getSubscribe(), Unlim1.getSubscribe(),
            BetaPlus1.getSubscribe(), BetaUnlim1.getSubscribe(),
            Plus1Promo.getSubscribe(), Unlim1Promo.getSubscribe(),
            Plus1Trial7.getSubscribe(), Plus1Trial.getSubscribe(),
            Unlim1Trial.getSubscribe()
        )

        private val threeMonthsSubscribeList = mutableListOf(
            Plus3.getSubscribe(), Unlim3.getSubscribe(),
            BetaPlus3.getSubscribe(), BetaUnlim3.getSubscribe(),
            Plus3Promo.getSubscribe(), Unlim3Promo.getSubscribe()
        )

        private val sixMonthsSubscribeList = mutableListOf(
            Plus6.getSubscribe(), Unlim6.getSubscribe(),
            BetaPlus6.getSubscribe(), BetaUnlim6.getSubscribe()
        )

        private val yearSubscribeList = mutableListOf(
            Plus12.getSubscribe(), Unlim12.getSubscribe(),
            BetaPlus12.getSubscribe(), BetaUnlim12.getSubscribe(),
            Plus12Promo.getSubscribe(), Unlim12Promo.getSubscribe(),
            Unlim12Discount.getSubscribe(), BetaUnlim12Discount.getSubscribe(),
            MinUnlim12Discount.getSubscribe(), MaxUnlim12Discount.getSubscribe(),
            Unlim12Trial.getSubscribe(), BetaUnlim12DiscountTrial.getSubscribe()
        )

        val discountSubscribeList = mutableListOf(
            Unlim12Discount, BetaUnlim12Discount, MinUnlim12Discount, MaxUnlim12Discount
        )

        val trialSubscribeList = mutableListOf(
            Plus0Trial3, Plus1Trial7, Plus1Trial,
            Unlim1Trial, Unlim0Trial7, Unlim12Trial,
            BetaUnlim12DiscountTrial, Unlim7Trial7
        )

        val betaSubscribeList = mutableListOf(
            BetaPlus0_7.getSubscribe(), BetaUnlim0_7.getSubscribe(),
            BetaPlus1.getSubscribe(), BetaUnlim1.getSubscribe(),
            BetaPlus3.getSubscribe(), BetaUnlim3.getSubscribe(),
            BetaPlus6.getSubscribe(), BetaUnlim6.getSubscribe(),
            BetaPlus12.getSubscribe(), BetaUnlim12.getSubscribe(),
            BetaUnlim12Discount.getSubscribe()
        )

        val plusList = mutableListOf(
            Plus0_7, Plus1, Plus3, Plus6, Plus12,
            BetaPlus0_7, BetaPlus1, BetaPlus3, BetaPlus6, BetaPlus12
        )
        val defaultPlusList = mutableListOf(BetaPlus0_7, BetaPlus1, Plus12)
        val plusPromoList = mutableListOf(Plus0_7Promo, Plus1Promo, Plus3Promo, Plus12Promo)

        val unlimList = mutableListOf(
            Unlim0_7, Unlim1, Unlim3, Unlim6, Unlim12,
            BetaUnlim0_7, BetaUnlim1, BetaUnlim3, BetaUnlim6, BetaUnlim12
        )
        val defaultUnlimList = mutableListOf(Unlim0_7, Unlim1, BetaUnlim12Discount)
        val unlimPromoList = mutableListOf(Unlim0_7Promo, Unlim1Promo, Unlim3Promo, Unlim12Promo)

        val giftsList = mutableListOf(GiftBronze, GiftSilver, GiftGold, GiftPlatinum)
        val fullGiftsList = {
            val list = mutableListOf<String>()
            giftsList.forEach { list.add(it.getSubscribe()) }
            list
        }

        val messagePackList = mutableListOf(
            MessagePack5, MessagePack10, MessagePack20, MessagePack50, MessagePack100,
            MessagePack500
        )
        val fullMessagePackList = {
            val list = mutableListOf<String>()
            messagePackList.forEach { list.add(it.getSubscribe()) }
            list
        }

        val fullPlusList = {
            val list = mutableListOf(
                Plus0Trial3.getSubscribe(), Plus1Trial7.getSubscribe(),
                Plus1Trial.getSubscribe()
            )
            plusList.forEach { list.add(it.getSubscribe()) }
            plusPromoList.forEach { list.add(it.getSubscribe()) }
            list
        }

        val fullUnlimList = {
            val list = mutableListOf(
                Unlim1Trial.getSubscribe(), Unlim0Trial7.getSubscribe(), Unlim12Trial.getSubscribe()
            )
            list.addAll(discountSubscribeList.map { it.getSubscribe() })
            list.addAll(unlimList.map { it.getSubscribe() })
            list.addAll(unlimPromoList.map { it.getSubscribe() })
            list
        }

        val fullSubscribeList = {
            val list = mutableListOf(
                Plus0Trial3, Plus1Trial7, Plus1Trial,
                Unlim1Trial, Unlim0Trial7, Unlim12Trial
            )
            list.addAll(trialSubscribeList)
            list.addAll(discountSubscribeList)
            list.addAll(plusList)
            list.addAll(plusPromoList)
            list.addAll(unlimList)
            list.addAll(unlimPromoList)
            list
        }

        private val fullPromoList = {
            val list = mutableListOf<String>()
            plusPromoList.forEach { list.add(it.getSubscribe()) }
            unlimPromoList.forEach { list.add(it.getSubscribe()) }
            list
        }

        fun isWeekSubscribe(subscribe: String) = weekSubscribeList.contains(subscribe)
        fun isMonthSubscribe(subscribe: String) = monthSubscribeList.contains(subscribe)
        fun is3MonthsSubscribe(subscribe: String) = threeMonthsSubscribeList.contains(subscribe)
        fun is6MonthsSubscribe(subscribe: String) = sixMonthsSubscribeList.contains(subscribe)
        fun isYearSubscribe(subscribe: String) = yearSubscribeList.contains(subscribe)
        fun isPlusSubscribe(subscribe: String) = fullPlusList().contains(subscribe)
        fun isUnlimSubscribe(subscribe: String) = fullUnlimList().contains(subscribe)
        fun isPromoSubscribe(subscribe: String) = fullPromoList().contains(subscribe)
        fun isTrialSubscribe(subscribe: String) =
            trialSubscribeList.map { it.getSubscribe() }.contains(subscribe)

        fun isDiscountSubscribe(subscribe: String) =
            discountSubscribeList.map { it.getSubscribe() }.contains(subscribe)

        fun isSubscribe(subscribe: String) =
            fullPlusList().contains(subscribe) || fullUnlimList().contains(subscribe)

        fun isGift(subscribe: String) = fullGiftsList().contains(subscribe)
        fun isMessagePack(subscribe: String) = fullMessagePackList().contains(subscribe)

        fun getMonthSubscribe(productIds: List<String>): String? {
            monthSubscribeList.forEach {
                if (productIds.contains(it)) return it
            }
            return null
        }

        fun getThreeMonthSubscribe(productIds: List<String>): String? {
            threeMonthsSubscribeList.forEach {
                if (productIds.contains(it)) return it
            }
            return null
        }

        fun getSixMonthSubscribe(productIds: List<String>): String? {
            sixMonthsSubscribeList.forEach {
                if (productIds.contains(it)) return it
            }
            return null
        }

        fun getYearSubscribe(productIds: List<String>): String? {
            yearSubscribeList.forEach {
                if (productIds.contains(it)) return it
            }
            return null
        }

        fun getWeekSubscribe(productIds: List<String>): String? {
            weekSubscribeList.forEach {
                if (productIds.contains(it)) return it
            }
            return null
        }

        fun hasBetaSubscribe(productIds: List<String>): Boolean {
            betaSubscribeList.forEach {
                if (productIds.contains(it)) return true
            }
            return false
        }

        fun getPeriodByProductId(productId: String) = when {
            isMonthSubscribe(productId) -> SubscriptionPeriod.MONTH
            is3MonthsSubscribe(productId) -> SubscriptionPeriod.THREE_MONTH
            is6MonthsSubscribe(productId) -> SubscriptionPeriod.SIX_MONTH
            isYearSubscribe(productId) -> SubscriptionPeriod.YEAR
            else -> SubscriptionPeriod.WEEK
        }


        fun getBillingByProductId(productId: String?): Billings? {
            if (productId.isNullOrEmpty()) return null
            entries.forEach {
                if (it.getSubscribe() == productId) return it
            }
            return null
        }


        fun getBillingNameByProductId(productId: String): String {
            var subscribeName = ""
            subscribeName += if (isUnlimSubscribe(productId)) "Unlim" else "Plus"
            val periodOfSubscribe: String = when (getPeriodByProductId(productId)) {
                SubscriptionPeriod.WEEK -> "Week"
                SubscriptionPeriod.MONTH -> "Month"
                SubscriptionPeriod.THREE_MONTH -> "3 Months"
                SubscriptionPeriod.SIX_MONTH -> "6 Months"
                SubscriptionPeriod.YEAR -> "Year"
            }
            subscribeName += " $periodOfSubscribe"

            if (betaSubscribeList.contains(productId)) subscribeName += " Beta"

            if (isDiscountSubscribe(productId)) {
                subscribeName += " Discount"
            }

            if (isTrialSubscribe(productId)) subscribeName += " Trial"
            return subscribeName
        }


        fun getInAppNameByProductId(productId: String): String {
            val billing = getBillingByProductId(productId) ?: return ""
            return when (billing) {
                GiftBronze -> "Gift Bronze"
                GiftSilver -> "Gift Silver"
                GiftGold -> "Gift Gold"
                GiftPlatinum -> "Gift Platinum"
                MessagePack5 -> "Message Pack 5"
                MessagePack10 -> "Message Pack 10"
                MessagePack20 -> "Message Pack 20"
                MessagePack50 -> "Message Pack 50"
                MessagePack100 -> "Message Pack 100"
                MessagePack500 -> "Message Pack 500"
                else -> getBillingNameByProductId(productId)
            }
        }

        /*fun getFullBilling(productId: String): Billings? {
            values().forEach { if (it.getSubscribe() == productId) return it }
            return null
        }*/
    }
}

enum class SubscriptionPeriod {
    WEEK,
    MONTH,
    THREE_MONTH,
    SIX_MONTH,
    YEAR
}

@Serializable
data class BillingHistoryRecord(@SerialName("productId") val productId: String)