 */
class AccountEyeColorConverter {
    companion object {
        fun positionsToItem(position: Int?): AccountEyeColor {
            var item = AccountEyeColor.DO_NOT_SHOW
            enumValues<AccountEyeColor>().forEach { if (position == it.position) item = it }
            return item
        }
    }
}