package kotpref.models.account

import kotpref.models.Id
import kotpref.models.getDefaultId
import kotlinx.serialization.SerialName

/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 2019-04-11.
 */
@kotlinx.serialization.Serializable
data class AccountPhoto(
    @SerialName("id") var id: Id = getDefaultId(),
    @SerialName("path") var path: String? = null,
    @SerialName("name") var name: String? = null,
    @SerialName("ext") var ext: String? = null,
    @SerialName("url") var url: String? = null,

    @SerialName("weapon_score") var weaponScore: Double? = null,
    @SerialName("alcohol_score") var alcoholScore: Double? = null,
    @SerialName("drugs_score") var drugsScore: Double? = null,
    @SerialName("offensive_score") var offensiveScore: Double? = null,
    @SerialName("nudity_score") var nudityScore: Double? = null,
    @SerialName("nudity_partial_score") var nudityPartialScore: Double? = null,
    @SerialName("is_private") var isPrivate: Boolean? = null,
    @SerialName("is_moderated") var isModerated: Boolean? = null,
    @SerialName("sort_id") var sortId: Int? = null
) {

    fun isSensitiveContent(): Boolean {
        val weaponScore = weaponScore ?: 0.0
        val alcoholScore = alcoholScore ?: 0.0
        val drugsScore = drugsScore ?: 0.0
        val offensiveScore = offensiveScore ?: 0.0
        val nudityScore = nudityScore ?: 0.0
        val nudityPartialScore = nudityPartialScore
        return ((nudityPartialScore ?: 0.0) > 0.10)
                //|| (nudityPartialScore == null && nudityScore > 0.01)
                || nudityScore > 0.01 || nudityScore == 0.0
                || weaponScore > 0.01 || weaponScore == 0.0
                || alcoholScore > 0.01 || alcoholScore == 0.0
                || drugsScore > 0.01 || drugsScore == 0.0
                || offensiveScore > 0.01 || offensiveScore == 0.0
    }
}

enum class SensitiveType { FULL, ON, OFF }