let stripe = null;
let elements = null;
let card = null;
let paymentRequest = null;
let paymentElement = null;

// Callbacks for payment methods
let onPaymentMethodReceivedCard = null;
let onPaymentMethodReceivedGoogle = null;
let onPaymentMethodReceivedApple = null;
let onPaymentMethodReceivedPayPal = null;

export function initStripe(publicKey) {
    if (!window.Stripe) {
        console.error("Stripe.js not loaded. Make sure to include it in your index.html.");
        return;
    }
    stripe = Stripe(publicKey);
    elements = stripe.elements();
}

// --- Card Payment Methods ---

// This function now also takes a callback
export function setupCardElement(elementId, onPaymentMethodCallback) {
    if (!elements) {
        console.error("Stripe elements not initialized. Call initStripe first.");
        return;
    }
    if (card) {
        card.unmount(); // Unmount previous card element if it exists
    }
    card = elements.create("card", {
                                         style: {
                                             base: {
                                                 color: "#FFFFFF", // Белый текст
                                                 fontSize: "16px",
                                                 fontFamily: "Arial, sans-serif",
                                                 fontSmoothing: "antialiased",
                                                 "::placeholder": { // Плейсхолдер
                                                     color: "#A0A0A0"
                                                 }
                                             },
                                             invalid: {
                                                 color: "#FA755A", // Красный для ошибок
                                                 iconColor: "#FA755A"
                                             },
                                             // Дополнительные состояния:
                                             focus: {
                                                 color: "#424770" // Например, синий при фокусе
                                             },
                                             complete: {
                                                 color: "#32CD32" // Зеленый при полном вводе
                                             }
                                         }
                                     });
    card.mount(`#${elementId}`);
    console.log("Stripe setupCardElement success.");
    onPaymentMethodReceivedCard = onPaymentMethodCallback; // Store the callback
}

export function unmountCardElement() {
    if (card) {
        card.unmount();
        card = null;
    }
    onPaymentMethodReceivedCard = null; // Clear the callback as well
}

// This function will now trigger the callback upon successful payment method creation
export async function triggerCardPaymentMethodCreation() {
    if (!stripe || !card) {
        console.error("Stripe or card element not initialized.");
        if (onPaymentMethodReceivedCard) {
            onPaymentMethodReceivedCard(null, "Stripe or card element not initialized."); // Pass error to callback
        }
        return;
    }

    const result = await stripe.createPaymentMethod({
        type: 'card',
        card: card,
    });

    if (result.error) {
        if (onPaymentMethodReceivedCard) {
            onPaymentMethodReceivedCard(null, result.error.message); // Pass error to callback
        }
    } else {
        if (onPaymentMethodReceivedCard) {
            onPaymentMethodReceivedCard(result.paymentMethod.id, null); // Pass success to callback
        }
    }
}

// This function now sets up the paymentRequest and returns availability
export async function initializePaymentRequest(amountInCents, currency, countryCode, label) {
    if (!stripe) {
        console.error("Stripe not initialized.");
        return { googlePay: false, applePay: false };
    }

    paymentRequest = stripe.paymentRequest({
        country: countryCode,
        currency: currency,
        total: { label: label, amount: amountInCents },
        requestPayerName: true,
        requestPayerEmail: true
    });

    const result = await paymentRequest.canMakePayment();
    return { googlePay: result?.googlePay === true, applePay: result?.applePay === true };
}

export function setGooglePayPaymentMethodCallback(callback) {
    onPaymentMethodReceivedGoogle = callback;
}

export function setApplePayPaymentMethodCallback(callback) {
    onPaymentMethodReceivedApple = callback;
}

// Listener for payment methods from Payment Request API
export function setupPaymentRequestListeners(clientSecret) {
    if (!paymentRequest) {
        console.error("Payment Request not initialized. Call initializePaymentRequest first.");
        return;
    }

    paymentRequest.on("paymentmethod", async (ev) => {
        const { error, paymentIntent } = await stripe.confirmCardPayment(
            clientSecret,
            { payment_method: ev.paymentMethod.id },
            { handleActions: false }
        );

        if (error) {
            ev.complete("fail");
            console.error("PaymentRequest Error:", error.message);
            return;
        }

        ev.complete("success");

        // Нужно ли проходить 3DS?
        if (paymentIntent.status === "requires_action") {
            const { error: actionError } = await stripe . confirmCardPayment (clientSecret);
            if (actionError) {
                console.error("3DS Error:", actionError.message);
                return;
            }
        }

        // Определяем тип платежа
        const wallet = ev.paymentMethod?.card?.wallet?.type;

        if (wallet === "google_pay" && onPaymentMethodReceivedGoogle) {
            onPaymentMethodReceivedGoogle(paymentIntent.id);
        } else if (wallet === "apple_pay" && onPaymentMethodReceivedApple) {
            onPaymentMethodReceivedApple(paymentIntent.id);
        } else {
            console.warn("Payment succeeded, but wallet type is not Google/Apple Pay.");
        }
    });
}

export function triggerPaymentRequest() {
    if (!paymentRequest) {
        console.error("Payment Request not initialized. Call initializePaymentRequest first.");
        return;
    }
    paymentRequest.show();
}

