export function setupPaymentElement(elementId, clientSecret, isSetup) {
    if (!stripe || !elements) {
        console.error("Stripe elements not initialized.");
        return;
    }

    const appearance = {
        theme: 'night',
    };

    console.log(`Payment Element in ${isSetup ? 'SETUP' : 'PAYMENT'} mode.`);

    const options = {
        clientSecret: clientSecret,
        appearance,
    };

    elements = stripe.elements(options);

    paymentElement = elements.create("payment", {
        layout: "tabs",
        wallets: {
            applePay: "never",
            googlePay: "never",
        },
    });
    paymentElement.mount(`#${elementId}`);
    console.log("Payment Element mounted.");
}

export async function confirmPayment(redirectIfRequired) {
    if (!stripe || !elements) {
        return { error: "Stripe or Elements not initialized." };
    }

    const opts = {
        elements,
        confirmParams: { /* return_url: отсутствует */ }
    };

    if (redirectIfRequired) {
        opts.redirect = 'if_required';
    } else {
        opts.redirect = 'if_required';
    }

    const result = await stripe.confirmPayment(opts);

    if (result.error) {
        return { error: result.error.message || "Unknown error", paymentIntent: result.paymentIntent };
    }
    return { error: null, paymentIntent: result.paymentIntent };
}

