package ui.managers

import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import kotlinx.browser.document
import org.w3c.dom.HTMLInputElement
import org.w3c.files.FileReader

@Composable
actual fun rememberCameraManager(
    onSuccess: (String) -> Unit,
    onError: () -> Unit
): CameraManager {
    val input = document.createElement("input") as HTMLInputElement
    input.type = "file"
    input.accept = "image/*"
    input.setAttribute("capture", "user")

    input.onchange = {
        val file = input.files?.item(0)
        if (file != null) {
            val reader = FileReader()
            reader.onload = {
                val result = reader.result as? String
                if (result != null) onSuccess(result)
                else onError()
            }
            reader.onerror = { onError() }
            reader.readAsDataURL(file) // читаем фото как base64
        } else onError()
    }

    return remember {
        CameraManager{
            input.click()
        }
    }
}

@Suppress("EXPECT_ACTUAL_CLASSIFIERS_ARE_IN_BETA_WARNING")
actual class CameraManager actual constructor(private val onLaunch: () -> Unit) {
    actual fun launch() {
        onLaunch()
    }
}