    fun connectWebSocket(appVersion: String, startConnect: Boolean = false) {
        CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
            val myAccount = accountRepository.getMyAccount()
            if (myAccount?.status != 5 && startConnect)
                chatRequests.connectWebSocket(appVersion, true)
        }
    }

    fun closeWebSocket() {
        if (!ChatRequests.isClose) {
            chatRequests.closeWebSocket()
        }
    }

    fun socketReconnectIfNeed() {
        CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
            val myAccount = accountRepository.getMyAccount()
            if (myAccount?.status != 5) chatRequests.socketReconnectIfClose()
        }
    }

