    /** Chats **/

    fun getChatByRest(
        recipientId: String,
        onSuccess: (ChatRoom?) -> Unit = {}, onError: (String?) -> Unit = {}
    ) {
        chatRequests.getChatByRest(recipientId,
            onSuccess = {
                val chatRoom = it?.data
                CoroutineScope(Dispatchers.Main).launch { onSuccess(chatRoom) }
            },
            onError = { CoroutineScope(Dispatchers.Main).launch { onError(it) } })
    }

    fun getChat(
        recipientId: String,
        onSuccess: (ChatDialog?) -> Unit = {}, onError: (String?) -> Unit = {}
    ) {
        chatRequests.getChat(recipientId,
            onSuccess = {
                val chatRoom = JsonObjectConverter.stringToObject<ChatRoom>(it)
                CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                    val myAccountId = accountRepository.getMyAccount()?.id ?: ""
                    val dialog =
                        chatRoom?.let { converter.convertRoomToDialog(chatRoom, myAccountId) }
                    saveChat(dialog)
                    CoroutineScope(Dispatchers.Main).launch { onSuccess(dialog) }
                }
            },
            onError = { CoroutineScope(Dispatchers.Main).launch { onError(it) } })
    }

    fun createChat(
        profileId: String, messageItem: ChatMessageItem?,
        onSuccess: (ChatDialog?) -> Unit, onError: (String?) -> Unit = {},
        getMessages: () -> MutableList<ChatMessageItem>,
        updateMessageStatus: (ChatMessageItem?) -> Unit
    ) {

        chatRequests.createRequest(profileId, messageItem, onSuccess = {
            EventBusManager.post(UpdateChatLimitsCounter(true, profileId))

            val chatRoom = JsonObjectConverter.stringToObject<ChatRoom>(it)
            CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                val myAccountId = accountRepository.getMyAccount()?.id ?: ""
                val dialog =
                    chatRoom?.let { converter.convertRoomToDialog(chatRoom, myAccountId) }
                val chatId = dialog?.dialogId ?: ""
                saveChat(dialog)
                setCurrentChatId(chatId)
                val messages = getMessages()
                CoroutineScope(Dispatchers.Main).launch { onSuccess(dialog) }

                if (messages.isEmpty()) {
                    messageItem?.let { messageItem ->
                        updateMessageStatus(messageItem, myAccountId, chatId)
                    }
                } else {
                    messages.forEach { message ->
                        sendMessage(chatId.toInt(), message,
                            onSuccess = { updateMessageStatus(messageItem) },
                            onError = {
                                updateMessageStatus(messageItem)
                                if (it == "record not found" && profileId.isNotEmpty()) {
                                    EventBusManager.post(UserBlockAccount(profileId.toInt()))
                                }
                                CoroutineScope(Dispatchers.Main).launch { onError(it) }
                            })
                    }
                }
            }
        }, onError = {
            CoroutineScope(Dispatchers.Main).launch { onError(it) }
        })
    }

    private fun updateMessageStatus(
        messageItem: ChatMessageItem,
        myAccountId: String,
        chatId: String
    ) {
        val message =
            if (messageItem.type == 1) messageItem.getText() else messageItem.imageUrl
        val result = MessageResult(
            myAccountId.toInt(), chatId.toInt(), body = message,
            type = messageItem.type, uuid = messageItem.getId()
        )
        EventBusManager.post(NewMessageCurrentChat(result))
    }

    fun setCurrentChat(chatUserId: String?, chatId: String?) {
        chatRequests.networkSession.socketRequestsResponseManager().currentOpenChatUserId =
            chatUserId
        chatRequests.networkSession.socketRequestsResponseManager().currentOpenChatId = chatId
    }

    fun setCurrentChatId(chatId: String?) {
        chatRequests.networkSession.socketRequestsResponseManager().currentOpenChatId = chatId
    }

    fun loadHistory(
        chatId: String?, myAccountId: String, offset: Int = 0, limit: Int = saveMessagesCount,
        loadMore: Boolean = false, onSuccess: (ChatDialog?) -> Unit, onError: () -> Unit = {}
    ) {
        if (chatId.isNullOrEmpty()) return onError()
        chatRequests.loadHistory(chatId.toInt(), myAccountId, limit, offset,
            onSuccess = {
                if (it == null) {
                    onError()
                    return@loadHistory
                }
                CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                    val chatDialog = ChatDialog(
                        chatId, it.name, unreadCount = 0, mode = it.mode, isPinned = it.isPinned,
                        chatUsers = it.accounts
                    )

                    val accounts = mutableListOf<ChatUser>()
                    accounts.addAll(it.accounts)
                    accounts.add(converter.convertAccountToUser(accountRepository.getMyAccount()))

                    val messages =
                        converter.convertMessagesToItems(it.history, accounts, true)
                    chatDialog.messages = messages
                    if (!loadMore) saveChat(chatDialog)
                    CoroutineScope(Dispatchers.Main).launch { onSuccess(chatDialog) }
                }
            },
            onError = { CoroutineScope(Dispatchers.Main).launch { onError() } })
    }

    fun pinChat(
        chatId: String, isPinned: Boolean, onSuccess: () -> Unit, onError: () -> Unit = {}
    ) {
        chatRequests.pinChat(chatId, isPinned,
            onSuccess = {
                CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
