    fun deleteMessage(
        chatId: Int, messageId: String, forSelf: Boolean,
        onSuccess: () -> Unit, onError: (String?) -> Unit
    ) {
        chatRequests.deleteMessage(
            chatId, messageId, forSelf, onSuccess = {
                CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                    val chat = getChatById(chatId.toString())
                    val messageToDelete = chat?.messages?.firstOrNull { it.getId() == messageId }
                    chat?.messages?.remove(messageToDelete)
                    saveChat(chat)
                    CoroutineScope(Dispatchers.Main).launch { onSuccess() }
                }
            }, onError = onError
        )
    }

    fun deleteLocalMessage(chatId: Int, messageId: String) {
        CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
            val chat = getChatById(chatId.toString())
            val messageToDelete = chat?.messages?.firstOrNull { it.getId() == messageId }
            chat?.messages?.remove(messageToDelete)
            saveChat(chat)
