                }
            }, onError = { CoroutineScope(Dispatchers.Main).launch { onError() } }
        )
    }

    private val saveChatCount = 100
    val saveMessagesCount = 200

    fun loadChatsWithPin(
        offset: Int = 0, limit: Int = saveChatCount,
        onSuccess: (MutableList<ChatDialog>) -> Unit, onError: () -> Unit = {}
    ) {
        val chats = mutableListOf<ChatRoom>()
        chatRequests.loadChats(5, offset, true,
            onSuccess = { pinnedChats ->
                if (pinnedChats != null && !pinnedChats.data.isNullOrEmpty()) chats.addAll(
                    pinnedChats.data
                )

                chatRequests.loadChats(limit, 0, false,
                    onSuccess = {
                        if (it != null) chats.addAll(it.data)
                        CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                            val myAccountId = accountRepository.getMyAccount()?.id ?: ""
                            val chatDialogs = converter.convertToDialog(chats, myAccountId)
                            val size = chatDialogs.size
                            if (offset == 0) saveChats(
                                if (size > saveChatCount) chatDialogs.subList(0, saveChatCount)
                                else chatDialogs, false
                            )
                            updateChatUserStatus(chatDialogs)
                            CoroutineScope(Dispatchers.Main).launch { onSuccess(chatDialogs) }
                        }
                    }, onError = { CoroutineScope(Dispatchers.Main).launch { onError() } })
            },
            onError = { CoroutineScope(Dispatchers.Main).launch { onError() } })
    }

    fun loadChats(
        offset: Int = 0, limit: Int = saveChatCount,
        onSuccess: (MutableList<ChatDialog>) -> Unit, onError: () -> Unit = {}
    ) {
        chatRequests.loadChats(limit, offset, false, onSuccess = {
            val chats = mutableListOf<ChatRoom>()
            if (it != null) chats.addAll(it.data)

            CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                val myAccountId = accountRepository.getMyAccount()?.id ?: ""
                val chatDialogs = converter.convertToDialog(chats, myAccountId)
                val size = chatDialogs.size
                if (offset == 0) saveChats(
                    if (size > saveChatCount) chatDialogs.subList(0, saveChatCount)
                    else chatDialogs, false
                )
                updateChatUserStatus(chatDialogs)
                CoroutineScope(Dispatchers.Main).launch { onSuccess(chatDialogs) }
            }
        }, onError = { CoroutineScope(Dispatchers.Main).launch { onError() } })
    }

    fun loadRequests(
        offset: Int = 0, limit: Int = saveChatCount,
        onSuccess: (MutableList<ChatDialog>?) -> Unit, onError: () -> Unit = {}
    ) {
        chatRequests.loadRequests(limit, offset, onSuccess = {
            val chats = mutableListOf<ChatRoom>()
            if (it != null) chats.addAll(it.data)

            CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                val myAccountId = accountRepository.getMyAccount()?.id ?: ""
                val chatDialogs = converter.convertToDialog(chats, myAccountId)
                chatDialogs.forEach { chat -> chat.isRequest = true }
                val size = chatDialogs.size
                if (offset == 0) saveChats(
                    if (size > saveChatCount) chatDialogs.subList(0, saveChatCount)
                    else chatDialogs,
                    true
                )
                updateChatUserStatus(chatDialogs)
                CoroutineScope(Dispatchers.Main).launch { onSuccess(chatDialogs) }
            }
        }, onError = { CoroutineScope(Dispatchers.Main).launch { onError() } })
    }

    private fun updateChatUserStatus(chatDialogs: MutableList<ChatDialog>) =
        CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
            val myAccountId = accountRepository.getMyAccount()?.id ?: ""
            val accountsToSave = mutableListOf<Account>()
            chatDialogs.forEach { chat ->
                chat.chatUsers.forEach {
                    if (it.getId() != myAccountId) {
                        val account = accountRepository.getAccountById(it.getId())
                        if (account != null) {
                            account.isOnline = it.isOnline
                            account.lastActive = it.lastActiveAt
                            accountsToSave.add(account)
                        }
                    }
                }
            }
            accountRepository.saveAccounts(accountsToSave)
        }

    fun loadPinChats(onSuccess: (Int) -> Unit) {
        var size = 0
        CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
            getChats()?.forEach { if (it.isPinned) size += 1 }
            CoroutineScope(Dispatchers.Main).launch { onSuccess(size) }
        }
    }

    fun loadUnreadChats(
        onSuccess: (ChatUnreadCount?) -> Unit, onError: () -> Unit = {}
    ) {
        chatRequests.loadUnreadChats(onSuccess = { unreadChats ->
            CoroutineScope(Dispatchers.Main).launch { onSuccess(unreadChats) }
        }, onError = { CoroutineScope(Dispatchers.Main).launch { onError() } })
    }

    fun sendMessage(
        chatId: Int, messageItem: ChatMessageItem?,
        onSuccess: () -> Unit, onError: (String?) -> Unit
    ) {
        chatRequests.sendMessage(
            chatId, messageItem, onSuccess = {
                CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                    val chat = getChatById(chatId.toString())
                    messageItem?.let {
                        it.setStatusValue(ChatMessageStatus.SENT)
                        var messages = mutableListOf<ChatMessageItem>()
                        messages.addAll(chat?.messages ?: mutableListOf())
                        if (messages.size >= saveMessagesCount) {
                            messages.add(0, messageItem)
                            messages = messages.subList(0, saveMessagesCount)
                        } else messages.add(0, messageItem)
                        chat?.messages = messages
                    }
                    saveChat(chat)
                    val myAccountId = accountRepository.getMyAccount()?.id ?: ""
                    messageItem?.let { messageItem ->
                        updateMessageStatus(messageItem, myAccountId, chatId.toString())
                    }
                    CoroutineScope(Dispatchers.Main).launch { onSuccess() }
                }
            }, onError = onError
        )
    }

    fun sendGiftMessage(
        giftId: String, userId: Int, chatId: Int?, transactionId: String,
        onSuccess: () -> Unit, onError: (String?) -> Unit
    ) {
        chatRequests.sendGiftMessage(
            giftId,
            userId,
            chatId,
            accountRepository.platformInfoManager.getUUIDString(),
            transactionId,
            onSuccess = {
                CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                    var chat = getChatById(chatId.toString())

                    val currentOpenChatUserId =
                        chatRequests.networkSession.socketRequestsResponseManager().currentOpenChatUserId

                    val chatRoom = JsonObjectConverter.stringToObject<ChatRoom>(it)
                    if ((chatId == null || chat == null) && chatRoom != null) {
                        val myAccountId = accountRepository.getMyAccount()?.id ?: ""
                        chat = converter.convertRoomToDialog(chatRoom, myAccountId)
                        EventBusManager.post(CreateChatWithGift(chat))
                    } else {
                        val data =
                            JsonObjectConverter.stringToObject<MessageResult>(it) ?: return@launch
                        val currentChat = currentOpenChatUserId == data.recipientId.toString()
                        if (currentOpenChatUserId != null && currentChat) {
                            EventBusManager.post(NewGiftCurrentChat(data))
                        } else {
                            EventBusManager.post(NewGift(data))
                        }
                    }
                    saveChat(chat)
                    onSuccess()
                }
            },
            onError = onError
        )
    }

