    ///region Database
    suspend fun getChats(): MutableList<ChatDialog> =
        withContext((Default)) { database.getChatsList() }

    suspend fun getChatById(chatId: String): ChatDialog? =
        withContext(Default) { database.getChatById(chatId) }

    suspend fun saveChat(chat: ChatDialog?) =
        withContext(Default) { database.saveChat(chat) }

    fun saveMessage(chatId: String, message: ChatMessageItem) =
        CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
            val chat = getChatById(chatId) ?: ChatDialog(chatId, messages = mutableListOf())
            chat.messages?.add(message)
            withContext(Default) { database.saveChat(chat) }
        }

    fun deleteMessage(chatId: String, message: ChatMessageItem) =
        CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
            val chat = getChatById(chatId)
            val item = chat?.messages?.firstOrNull { it.getId() == message.getId() }
            chat?.messages?.remove(item)
            withContext(Default) { database.saveChat(chat) }
        }

    suspend fun deleteChat(chatId: String) =
        withContext(Default) { database.deleteChatById(chatId) }

    private suspend fun saveChats(chats: List<ChatDialog>?, isRequest: Boolean) =
        withContext(Default) { database.saveChats(chats, isRequest) }

    suspend fun getWows(): MutableList<ProfileWow>? =
        withContext((Default)) { database.getWowsList() }

    suspend fun saveWow(wow: ProfileWow?) = withContext(Default) { database.saveWow(wow) }

    suspend fun deleteWow(wowId: Int) =
        withContext(Default) { database.deleteWowById(wowId) }

    private suspend fun saveWows(wows: List<ProfileWow>?) = withContext(Default) {
        database.saveWows(wows)
    }
    ///endregion
}