package managers

import androidx.compose.ui.graphics.toComposeImageBitmap
import dependencies.CameraInterop
import dependencies.GalleryInterop
import kotpref.utils.IPickPhotoManager
import org.jetbrains.skia.Image.Companion.makeFromEncoded
import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi

class PickPhotoManager : IPickPhotoManager {

    override fun showPickFromCamera(pickCameraPhoto: (Any?) -> Unit) {
        try {
            GalleryInterop.selectImage(
                onSuccess = {
                    val imageData = decodeBase64ToBytes(it)
                    if (imageData != null) {
                        val imageBitmap = makeFromEncoded(imageData).toComposeImageBitmap()
                        pickCameraPhoto(imageBitmap)
                    } else {
                        println("PickPhotoManager: Не удалось декодировать изображение.")
                    }
                }, onError = {
                    println("PickPhotoManager: Error: ${it}")
                }
            )
        } catch (e: Throwable) {
            println("PickPhotoManager: Ошибка при выборе изображения: ${e.message}")
        }
    }

    override fun showPickFromGallery(pickGalleryPhoto: (Any?) -> Unit) {
        try {
            CameraInterop.takePhoto(onSuccess = {
                val imageData = decodeBase64ToBytes(it)
                if (imageData != null) {
                    val imageBitmap = makeFromEncoded(imageData).toComposeImageBitmap()
                    pickGalleryPhoto(imageBitmap)
                } else {
                    println("PickPhotoManager: Не удалось декодировать изображение.")
                }
            }, onError = {
                println("PickPhotoManager: Error: ${it}")
            })
        } catch (e: Throwable) {
            println("PickPhotoManager: Ошибка при захвате фото: ${e.message}")
        }
    }

    @OptIn(ExperimentalEncodingApi::class)
    fun decodeBase64ToBytes(base64String: String): ByteArray? {
        // Data URL имеет формат "data:image/png;base64,iVBORw0KGgo..."
        // Нужно убрать префикс, чтобы получить чистую base64 строку
        val prefix = "data:image/"
        val base64PrefixEnd = base64String.indexOf(";base64,")
        return if (base64PrefixEnd != -1) {
            val actualBase64 = base64String.substring(base64PrefixEnd + ";base64,".length)
            try {
                Base64.decode(actualBase64)
            } catch (e: IllegalArgumentException) {
                println("PickPhotoManager: Ошибка декодирования Base64: ${e.message}")
                null
            }
        } else {
            null
        }
    }

}