package ui.managers

import dependencies.AccountRepository
import fiori.sharedmodule.generated.resources.Res
import fiori.sharedmodule.generated.resources.dialog_stop_words_error
import fiori.sharedmodule.generated.resources.error_message_something_wrong
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotpref.models.AppVariant
import kotpref.models.Languages
import kotpref.models.account.Account
import kotpref.models.account.AccountFilter
import kotpref.utils.IDialogManager
import kotpref.utils.IPlatformInfoManager

sealed class OnBoardingUpdateAccountManagerEvent {
    data object ShowNextPage : OnBoardingUpdateAccountManagerEvent()
    data class LocationPermission(val onAccess: (Any?) -> Unit) :
        OnBoardingUpdateAccountManagerEvent()
    data class LoadPeopleSuccess(val peopleList: MutableList<Account>) :
        OnBoardingUpdateAccountManagerEvent()
}

class OnBoardingUpdateAccountManager(
    val routeTo: (OnBoardingUpdateAccountManagerEvent) -> Unit,
    val dialogManager: IDialogManager,
    val accountRepository: AccountRepository,
    val callBack: () -> Unit = {}
) {
    fun checkStopWordsAndUpdateAccount(account: Account?, deviceInfoManager: IPlatformInfoManager) {
        fun checkStopWords() {
            val aboutMe = account?.info?.about ?: ""
            if (aboutMe.isNotEmpty() && accountRepository.settingsStopWords().isNotEmpty()) {
                accountRepository.settingsStopWords().forEach {
                    if (aboutMe.contains(it)) {
                        dialogManager.showMessageDialog(Res.string.dialog_stop_words_error)
                        callBack()
                        return
                    }
                }
            }
            updateAccount(account, deviceInfoManager)
        }

        accountRepository.loadSettings({ checkStopWords() }, onError = { callBack() })
    }

    fun updateAccount(account: Account?, deviceInfoManager: IPlatformInfoManager) {
        accountRepository.loadMe(saveWithoutMerge = true, onSuccess = {
            if (!it?.info?.iamList.isNullOrEmpty()) account?.info?.iamList = null
            if (!it?.info?.birthday.isNullOrEmpty()) account?.info?.birthday = null
            if (it?.measurementUnits == null) {
                val countryCode = deviceInfoManager.getCountryCode()
                val language = deviceInfoManager.getLanguage()
                var measurementUnits = 1

                if (language == Languages.ENGLISH.locale) {
                    if (countryCode == "us" || AppVariant.isFiorryOrHeaven()) measurementUnits = 2
                }

                account?.measurementUnits = measurementUnits
            }
            if ((it?.subscriptionStatus?.subscription?.type ?: 0) > 0) {
                account?.subscriptionStatus = it?.subscriptionStatus
            }

            accountRepository.updateAccount(account, onSuccess = {
                CoroutineScope(Dispatchers.Main).launch {
                    val filter = accountRepository.getMyFilter() ?: AccountFilter()
                    if (!it?.info?.compatibilityAnswers.isNullOrEmpty()) {
                        filter.filters.withQuestionnaire = true
                        accountRepository.saveAccountFilter(filter)
                    }
                    loadPeopleIfCan(it, filter)
                }
            }, onError = {
                callBack()
                dialogManager.showMessageDialog(Res.string.error_message_something_wrong)
            })
        }, onError = {
            callBack()
            dialogManager.showMessageDialog(Res.string.error_message_something_wrong)
        })
    }

    fun loadPeopleIfCan(myAccount: Account?, filter: AccountFilter) {
        routeTo(
            OnBoardingUpdateAccountManagerEvent.LocationPermission {
                routeTo(OnBoardingUpdateAccountManagerEvent.ShowNextPage)
                callBack()
                if (it == null) return@LocationPermission
                val lat = accountRepository.locationUtils.lastLat
                val lon = accountRepository.locationUtils.lastLon
                if (lat != 0.0 && lon != 0.0) {
                    filter.localLat = lat
                    filter.localLon = lon
                    CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                        accountRepository.saveAccountFilter(filter)
                    }

                    accountRepository.updateUserCity(lat, lon, onSuccess = {
                        loadPeople(myAccount, filter)
                    })
                }
            }
        )
    }

    private fun loadPeople(myAccount: Account?, filter: AccountFilter) {
        val limit = when (myAccount?.subscriptionStatus?.subscription?.type ?: 0) {
            2 -> 96
            1 -> 500
            else -> 150
        }
        accountRepository.loadAccountsByFilter(filter, 0, limit, onSuccess = {
            routeTo(OnBoardingUpdateAccountManagerEvent.LoadPeopleSuccess(it ?: mutableListOf()))
        })
    }
}