package kotpref.models.account.enums

import fiori.sharedmodule.generated.resources.Res
import fiori.sharedmodule.generated.resources.accommodation_do_not_show
import fiori.sharedmodule.generated.resources.sex_position_bottom
import fiori.sharedmodule.generated.resources.sex_position_bottom_paradiz
import fiori.sharedmodule.generated.resources.sex_position_top
import fiori.sharedmodule.generated.resources.sex_position_top_paradiz
import fiori.sharedmodule.generated.resources.sex_position_versatile
import fiori.sharedmodule.generated.resources.sex_position_versatile_paradiz
import kotpref.models.AppVariant
import org.jetbrains.compose.resources.StringResource

/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 2019-05-07.
 */
enum class AccountSexPosition(val resId: () -> StringResource, val value: String) {
    DO_NOT_SHOW({ Res.string.accommodation_do_not_show }, "do_not_show"),
    TOP({
        when {
            AppVariant.isParadiz() -> Res.string.sex_position_top_paradiz
            else -> Res.string.sex_position_top
        }
    }, "top"),
    VERSATILE({
        when {
            AppVariant.isParadiz() -> Res.string.sex_position_versatile_paradiz
            else -> Res.string.sex_position_versatile
        }
    }, "vers"),
    BOTTOM({
        when {
            AppVariant.isParadiz() -> Res.string.sex_position_bottom_paradiz
            else -> Res.string.sex_position_bottom
        }
    }, "bottom")
}