enum class CompatibilityCategory(val group: String) {
    Average(""),
    Goals("goals"),
    Libido("libido"),
    Sexual("sex"),
    Lifestyle("lifestyle"),
    Mindset("mindset"),
    Extreme("extreme"),
    Habits("habits");

    companion object {
        fun sortQuestions(questions: MutableList<CompatibilityQuestion>): MutableList<CompatibilityQuestion> {
            return questions.sortedBy { it.sortId }.sortedBy {
                val category = getCategoryByGroup(it.group ?: "")
                category.ordinal
            }.toMutableList()
        }

        fun getCategoryByGroup(group: String): CompatibilityCategory {
            var category = if (AppVariant.isParadiz()) Libido else Lifestyle
            values().forEach { if (it.group == group) category = it }
            return category
        }

        fun getAllCategories() : MutableList<CompatibilityCategory>{
            return if (AppVariant.isParadiz()) {
                mutableListOf(Average, Goals, Libido, Sexual, Mindset, Extreme)
            } else if (AppVariant.isElizium()) {
                mutableListOf(Average, Goals, Sexual, Lifestyle, Mindset, Habits)
            } else {
                mutableListOf(Average, Lifestyle, Sexual, Goals, Mindset, Habits)
            }
        }
    }
}