import fiori.sharedmodule.generated.resources.people_distance_km
import fiori.sharedmodule.generated.resources.people_distance_meters
import fiori.sharedmodule.generated.resources.people_distance_mi
import kotpref.models.AppVariant
import ui.resources.ResManager.getString

