class MeasurementConverter {

    companion object {

        /**
         * @param lb - pounds
         */
        val lbCoef = 2.20462262

        fun lbToKgConverter(lb: Int): Int {
            val kg = (lb / lbCoef).toInt()
            val newLb = kgToLbConverter(kg.toDouble())
            return when {
                newLb == lb -> kg
                newLb < lb -> ((lb - newLb) / lbCoef).toInt() + kg
                else -> ((lb - newLb) / lbCoef).toInt() + kg
            }
        }

        fun kgToLbConverter(kg: Double): Int {
            val lb = kg * lbCoef
            return if (lb % 5 >= 2.5) ((lb / 5).toInt() + 1) * 5 else (lb / 5).toInt() * 5
        }


        /**
         * @param cm - centimeters
         */
        fun cmToInchConverter(cm: Double): String {
            val ft = (cm / 30.48).toInt()
            val inch = ((cm % 30.48) / 2.54).toInt()
            return "$ft' $inch\""
        }

        fun cmToInchConverter(cm: Int): String = cmToInchConverter(cm.toDouble())


        private fun metersToYards(meters: Int) = meters * 1.0936133
        private fun metersToMiles(meters: Int) = meters / 1609.33999997549
        private fun metersToKm(meters: Int) = meters / 1000.0
        private fun milesToMeters(miles: Double) = miles * 1609.33999997549

        suspend fun kmToString(distance: Int, isMetric: Boolean): String {
            val startValue = if (isMetric) 1000 else milesToMeters(1.0).toInt()
            val meters =
                distance//if (distance > 500) distance else (distance + Random().nextInt(100))
            val m = getString(Res.string.people_distance_meters)
            val km = getString(Res.string.people_distance_km)
            val mi = getString(Res.string.people_distance_mi)

            val isKyivDate = AppVariant.isEliziumOrParadiz()
            return when {
                isKyivDate && meters < 50 && isMetric -> "<50 $m"
                isKyivDate && meters < milesToMeters(0.05) && !isMetric -> "<0.05 $mi"

                !isKyivDate && meters < 500 && isMetric -> "<500 $m"
                !isKyivDate && meters < milesToMeters(0.5) && !isMetric -> "<0.5 $mi"

                meters < startValue -> if (isMetric) "$meters $m"
                else "${metersToMiles(meters)} $mi"// формат 2 знака после запятой !!!

                isMetric && meters == 1000 -> "1 $km"
                !isMetric && meters == milesToMeters(1.0).toInt() -> "1 $mi"

                meters in startValue..29999 -> {
                    val value =
                        if (isMetric) metersToKm(meters).toInt() else metersToMiles(meters).toInt()
                    val stringEnd = if (isMetric) km else mi
                    //String.format(Locale.US, "%.2f", value) + " $stringEnd"
                    "$value $stringEnd"
                }
                else -> if (isMetric) "${metersToKm(meters).toInt()} $km"
                else "${metersToMiles(meters).toInt()} $mi"
            }
        }
    }
}