object LocalStorageManager {

    fun saveString(key: String, value: String) {
        try {
            localStorage.setItem(key, value)
            //println("LocalStorageManager: --> save key = $key; value = $value")
        } catch (e: Throwable) {
            //println("LocalStorageManager: Failed to save to localStorage $e")
        }
    }

    fun getString(key: String): String? {
        return try {
            val value = localStorage.getItem(key)
            //println("LocalStorageManager: <-- get key = $key; value = $value")
            value
        } catch (e: Throwable) {
            //println("LocalStorageManager: Failed to read from localStorage $e")
            null
        }
    }

    fun saveBoolean(key: String, value: Boolean) {
        saveString(key, value.toString())
    }

    fun getBoolean(key: String): Boolean? {
        return getString(key)?.toBooleanStrictOrNull()
    }

    fun saveInt(key: String, value: Int) {
        saveString(key, value.toString())
    }

    fun getInt(key: String): Int? {
        return getString(key)?.toIntOrNull()
    }

    fun saveLong(key: String, value: Long) {
        saveString(key, value.toString())
    }

    fun getLong(key: String): Long? {
        return getString(key)?.toLongOrNull()
    }


    fun remove(key: String) {
        try {
            localStorage.removeItem(key)
        } catch (e: Throwable) {
            //println("LocalStorageManager: Failed to remove from localStorage $e")
        }
    }

    fun clear() {
        try {
            localStorage.clear()
        } catch (e: Throwable) {
            //println("LocalStorageManager: Failed to clear localStorage $e")
        }
    }
}

