 */
class AccountHairColorConverter {
    companion object {
        fun positionsToItem(position: Int?): AccountHairColor {
            var item = AccountHairColor.DO_NOT_SHOW
            enumValues<AccountHairColor>().forEach { if (position == it.position) item = it }
            return item
        }
    }
}