enum class ErrorField { DisplayName, Password, Email, Birthday, All }

sealed class SplashSignUpAboutEvent {
    data object OnBoardingStart : SplashSignUpAboutEvent()
    data class ShowBirthdayPicker(
        val currentBirthday: String, val callback: (String) -> Unit
    ) : SplashSignUpAboutEvent()

    data object HideKeyboard : SplashSignUpAboutEvent()
    data object OnBackClick : SplashSignUpAboutEvent()
    data class SplashSignInEmail(
        val authorizationType: AuthorizationType, val password: String, val email: String
    ) : SplashSignUpAboutEvent()
}

class SplashSignUpAboutVM(
    private val authorizationType: String,
    private val social: AuthorizationSocial?,
    private val obtainEvent: (SplashSignUpAboutEvent) -> Unit
) : ViewModel() {

    val type = AuthorizationType.valueOf(authorizationType)
    val dialogManager by di.instance<IDialogManager>()
    val repositoriesProvider by di.instance<RepositoriesProvider>()
    private val platformInfoManager by di.instance<IPlatformInfoManager>()
    val amplitudeManager by di.instance<AmplitudeManager>()

    val emailType = type == AuthorizationType.EMAIL
    private val appKeys = repositoriesProvider.appKeys
    private val accountRepository = repositoriesProvider.accountRepository

    val nicknameValue = mutableStateOf("")
    val nicknameError = mutableStateOf("")
    val emailValue = mutableStateOf(TextFieldValue(""))
    val emailValueString = mutableStateOf("")
    val emailError = mutableStateOf("")
    val passwordValue = mutableStateOf("")
    val passwordError = mutableStateOf("")
    var birthdayDate = LocalDate.now()
    val birthdayValue = mutableStateOf("")
    val birthdayError = mutableStateOf("")
    val checkedEmail = mutableStateOf(true)
    val showProgress = mutableStateOf(false)
    val showRecaptcha = mutableStateOf(false)

    var passwordGenerated = false

    val showBirthdayPicker = mutableStateOf(false)

    init {
        if (AppVariant.isLocalSettings()) {
            nicknameValue.value = GeneralConstants.nickname
            emailValue.value = TextFieldValue(GeneralConstants.email)
            emailValueString.value = emailValue.value.text
            birthdayDate = LocalDate(2000, 1, 1)
            birthdayValue.value = "1 January 2000"
        }

        if (AppVariant.isWeb()) {
            amplitudeManager.sendEvent(AmplitudeEvent.WebFunnelEmailShown)
        } else {
            amplitudeManager.sendEvent(AmplitudeEvent.OnboardingCreateProfileScreenShown)
        }
        accountRepository.getAppKeys().startOnboarding = false
        when (type) {
            AuthorizationType.FACEBOOK, AuthorizationType.GOOGLE -> {
                emailValue.value = TextFieldValue(
                    social?.email ?: "",
                    selection = TextRange(social?.email?.length ?: 0)
                )
            }

            else -> {
                if (AppVariant.isWeb()) {
                    passwordValue.value = generatePassword()
                    if (passwordValue.value.isNotEmpty()) passwordGenerated = true
                }

                if (AppVariant.isLocalSettings()) {
                    passwordValue.value = GeneralConstants.password
                }
            }
        }

        CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
            val myAccount = accountRepository.getMyAccount()
            val nickname = myAccount?.nickname
            val email = myAccount?.email
            //if (!nickname.isNullOrEmpty()) nicknameValue.value = nickname
            if (!email.isNullOrEmpty()) emailValue.value = TextFieldValue(email)
        }
    }

    fun hideErrorByField(errorField: ErrorField) {
        viewModelScope.launch(Dispatchers.Main) {
            if (nicknameError.value == ResManager.getString(Res.string.auth_sign_in_incorrect_latin_display_name)) {
                hideError(ErrorField.DisplayName)
            }
        }

        when (errorField) {
            ErrorField.DisplayName -> hideError(ErrorField.DisplayName)
            ErrorField.Birthday -> hideError(ErrorField.Birthday)
            ErrorField.Email -> hideError(ErrorField.Email)
            else -> {}
        }
    }

    fun showBirthdayPicker(onDown: () -> Unit) {
        showBirthdayPicker.value = true
        hideErrorByField(ErrorField.Birthday)
        obtainEvent(SplashSignUpAboutEvent.ShowBirthdayPicker(birthdayValue.value) {
            birthdayValue.value = it
            onDown.invoke()
        })
//        router.route(Destination.DatePicker(birthdayValue.value, callback = {
//            hideErrorByField(ErrorField.Birthday)
//            birthdayValue.value = it
//            onDown.invoke()
//        }))
    }

    fun onDoneClickPickerCompose(date: LocalDate, months: List<String>, onDown: () -> Unit) {
        hideError(ErrorField.Birthday)
        birthdayDate = date
        birthdayValue.value = "${date.dayOfMonth} ${months[date.monthNumber - 1]} ${date.year}"

        onDown.invoke()
    }

    fun continueSignUp(isDuplicate: Boolean = false) {
        when (type) {
            AuthorizationType.EMAIL -> {
                if (isDuplicate) AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.createProfileEmailNextTop.name)
                else AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.createProfileEmailNextBottom.name)
            }

            AuthorizationType.FACEBOOK -> {
                if (isDuplicate) AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.createProfileFacebookNextTop.name)
                else AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.createProfileFacebookNextBottom.name)
            }

            AuthorizationType.GOOGLE -> {
                if (isDuplicate) AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.createProfileGoogleNextTop.name)
                else AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.createProfileGoogleNextBottom.name)
            }

            else -> {
                if (isDuplicate) AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.createProfilePhoneNextTop.name)
                else AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.createProfilePhoneNextBottom.name)
            }
        }

        amplitudeManager.sendEvent(AmplitudeEvent.OnboardingCreateProfileScreenNextClicked)

        showProgress.value = true
        if (toShow) return

        checkErrors()
    }

    private var toShow = false
    private var recaptchaResponseTime = 0L

    fun checkErrors() {
        viewModelScope.launch(Dispatchers.Main) { /* runBlocking */
            if (toShow) return@launch
            toShow = true
            hideError()

            var haveError = false
            val displayNameError =
                checkDisplayNameError(ResManager.getString(Res.string.auth_sign_in_incorrect_display_name))
            val birthdayError =
                checkBirthdayError(ResManager.getString(Res.string.pick_date_age_less_18_text))
            val emailError =
                checkEmailError(ResManager.getString(Res.string.auth_sign_in_incorrect_email))
            val passwordError =
                checkPasswordError(ResManager.getString(Res.string.error_message_sign_password_at_least))

            delay(1000L)
            haveError = birthdayError || displayNameError || emailError || passwordError
            if (haveError) {
                showProgress.value = false
                toShow = false
                return@launch
            }

            createAccount()
        }
    }

    fun createAccount() {
        viewModelScope.launch(Dispatchers.Main) {
            var account = accountRepository.getMyAccount()
            if (account == null) account = Account(
                "", accountRepository.getAppKeys().userLogin
            )
            val displayName = nicknameValue.value.trim()
            account.nickname = displayName.replace(" +".toRegex(), " ")

            var email = emailValue.value.text.trim()
            if (email.isNotEmpty()) account.email = email

            val startCaptchaTime = DateTimeConverter.currentTimeMillis()

            showingRecaptcha = true
            if (appKeys.countErrorCaptcha >= 5) {
                accountRepository.banError()
                return@launch
            }

            showRecaptcha.value = true

            fun registerAccountWithReCaptchaToken(recaptchaToken: String? = null) {
                val birthday = DateTimeConverter.dateToString(
                    LocalDateTime(
                        birthdayDate,
                        LocalTime(0, 0, 0)
                    )
                )
                val password = passwordValue.value
                registerAccount(account, birthday, password, recaptchaToken)
            }

            if (accountRepository.settingsRecaptchaEnabled()) platformInfoManager.showReCaptcha(
                onSuccess = { recaptchaToken ->
                    val currentTime = DateTimeConverter.currentTimeMillis()
                    if (currentTime - recaptchaResponseTime < 1000) return@showReCaptcha

                    recaptchaResponseTime = currentTime
                    val finishCaptchaTime = DateTimeConverter.currentTimeMillis()
                    if (finishCaptchaTime - startCaptchaTime > 1000L * 10 && !AppVariant.isDebug()) {
                        closeRecaptcha()
                    } else {
                        showingRecaptcha = false
                        showRecaptcha.value = false
                        registerAccountWithReCaptchaToken(recaptchaToken)
                    }
                },
                onFailure = { message ->
                    val currentTime = DateTimeConverter.currentTimeMillis()
                    if (currentTime - recaptchaResponseTime > 1000) {
                        showProgress.value = false
                        toShow = false
                        message?.let { dialogManager.showMessageDialog(it) }
                        return@showReCaptcha
                    }
                    recaptchaResponseTime = currentTime
                    closeRecaptcha()
                }
            )
            else registerAccountWithReCaptchaToken()
        }
    }

    fun checkDisplayNameError(error: String): Boolean {
        val displayName = nicknameValue.value.trim()
        if (displayName.isEmpty()) {
            setDisplayNameErrorText(error)
            return true
        }
        return false
    }

    fun checkBirthdayError(error: String): Boolean {
        val currentDate = DateTimeConverter.getCurrentDate()
        val birthdayDate = birthdayDate.atTime(1, 0)
        val diffYears = DateTimeConverter.periodDifference(birthdayDate, currentDate).years
        if (diffYears < 18) {
            AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.selectedLess18.name)
            setBirthdayErrorText(error)
            return true
        }
        return false
    }

    fun checkEmailError(emailErrorText: String): Boolean {
        var email = emailValue.value.text.trim()
        if (email.isEmpty()) email = emailValueString.value
        val isEmailValid = EmailValid.isEmailValid(email)
        if ((email.isEmpty() && emailType) || (email.isNotEmpty() && !isEmailValid)) {
            setEmailErrorText(emailErrorText)
            return true
        }
        return false
    }

    fun checkPasswordError(passwordErrorText: String): Boolean {
        val password = passwordValue.value
        if ((password.isEmpty() || password.length < 6) && social == null) {
            passwordError.value = passwordErrorText
            return true
        }
        return false
    }


    fun checkEmailOnServer(emailErrorText: String, onSuccess: () -> Unit) {
        val haveEmailError = checkEmailError(emailErrorText)
        if (haveEmailError) return

        var email = emailValue.value.text
        if (email.isEmpty()) email = emailValueString.value
        showProgress.value = true
        accountRepository.accountRequests.checkEmailAddress(
            email,
            onSuccess = {
                showProgress.value = false
                onSuccess()
            },
            onError = {
                showProgress.value = false
                emailError.value = it ?: ""
                amplitudeManager.sendEvent(AmplitudeEvent.WebFunnelEmailWrong)
            }
        )
    }

    private var showingRecaptcha = false

    private fun closeRecaptcha() {
        if (!showingRecaptcha) return
        showingRecaptcha = false
        showRecaptcha.value = false

        if (appKeys.countErrorCaptcha > 4 && !AppVariant.isDebug()) {
            accountRepository.banDevice({})
        }
        val message =
            Res.string.dialog_verification_captcha_error
        dialogManager.showMessageDialog(message)

        showProgress.value = false
        toShow = false
        appKeys.countErrorCaptcha++
    }

    private fun registerAccount(
        account: Account, birthday: String, password: String, recaptchaToken: String?
    ) {
        showProgress.value = true

        fun onSuccess() {
            if (!checkedEmail.value) {
                accountRepository.changeAccountNotification(AccountNotifications(email = false))
            }
            appKeys.webRegisterPassword = password
            showProgress.value = false
            toShow = false
            AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.selected18orMore.name)
            sendEvent(account.email)
            //router.route(Destination.OnBoardingStart())
            //onShowNextPage()
            obtainEvent(SplashSignUpAboutEvent.OnBoardingStart)
            ResponseCallback.callRetriesForNotValidTokens = false
            if (AppVariant.isWeb()) amplitudeManager.sendEvent(AmplitudeEvent.WebFunnelAccountCreateSuccess)
        }

        fun onError(
            errorText: String? = "",
            isEmailError: Boolean = false
        ) {
            showProgress.value = false
            toShow = false
//            binding.signUpBtn.isEnabled = true
            if (!errorText.isNullOrEmpty()) dialogManager.showMessageDialog(message = errorText)
            showError(errorMessage = errorText, isEmailError = isEmailError)
            ResponseCallback.callRetriesForNotValidTokens = false
            if (AppVariant.isWeb()) amplitudeManager.sendEvent(AmplitudeEvent.WebFunnelAccountCreateError)
        }

        ResponseCallback.callRetriesForNotValidTokens = true
        when (type) {
            AuthorizationType.FACEBOOK -> {
                accountRepository.createAccountWithFacebook(
                    social?.tokenId ?: social?.id, social?.token, account.nickname ?: "",
                    account.email,
                    birthday, platformInfoManager.getAppVersion(), recaptchaToken, {
                        amplitudeManager.sendEvent(
                            AmplitudeEvent.FacebookRegisterSuccess(
                                social?.id, social?.token, account.email, social?.tokenId,
                                it?.accountId
                            )
                        )
                        accountRepository.getAppKeys().registrationByFacebook = true
                        onSuccess()
                    }, onError = {
                        amplitudeManager.sendEvent(
                            AmplitudeEvent.FacebookRegisterError(
                                social?.id, social?.token, account.email, social?.tokenId, it
                            )
                        )
                        onError(it)
                    })
            }

            AuthorizationType.GOOGLE -> {
                accountRepository.createAccountWithGoogle(
                    social?.tokenId ?: social?.id, social?.token,
                    account.email,
                    account.nickname ?: "",
                    birthday, platformInfoManager.getAppVersion(), recaptchaToken,
                    {
                        amplitudeManager.sendEvent(
                            AmplitudeEvent.GoogleRegisterSuccess(
                                social?.id, social?.token, account.email, social?.tokenId,
                                it?.accountId
                            )
                        )
                        onSuccess()
                    }, onError = {
                        amplitudeManager.sendEvent(
                            AmplitudeEvent.GoogleRegisterError(
                                social?.id, social?.token, account.email, social?.tokenId, it
                            )
                        )
                        onError(it)
                    })
            }

            AuthorizationType.EMAIL -> {
                val email = account.email ?: ""
                amplitudeManager.sendEvent(AmplitudeEvent.EmailRegisterStart(email))

                accountRepository.registerEmailAccount(
                    email, password, account.nickname ?: "",
                    birthday, platformInfoManager.getAppVersion(), recaptchaToken, onSuccess = {
                        amplitudeManager.sendEvent(
                            AmplitudeEvent.EmailRegisterSuccess(email, it?.accountId)
                        )
                        AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.registrationSuccessEmail.name)
                        onSuccess()
                    }, onError = {
                        amplitudeManager.sendEvent(AmplitudeEvent.EmailRegisterError(email, it))
                        onError(it, true)
                    })
            }

            else -> {
                accountRepository.registerPhoneAccount(
                    account.login ?: "", password, account.nickname ?: "",
                    account.email, birthday, platformInfoManager.getAppVersion(), onSuccess = {
                        AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.registrationSuccessMobile.name)
                        onSuccess()
                    }, onError = { onError(it) })
            }
        }
    }


    fun showError(
        error: StringResource? = Res.string.string_empty,
        errorMessage: String? = null,
        isEmailError: Boolean = false,
        isBirthdayError: Boolean = false
    ) {
        viewModelScope.launch(Dispatchers.Main) {
            val accountPasswordError =
                ResManager.getString(Res.string.error_message_sign_up_password)
            val accountCredentialsError =
                ResManager.getString(Res.string.error_message_sign_up_account_credentials)
            val accountEmailError =
                ResManager.getString(Res.string.error_message_sign_up_account_email_use)
            val errorText = errorMessage ?: error?.let { ResManager.getString(it) }
            if (
                isEmailError && (errorText?.contains(accountCredentialsError) == true ||
                        errorText?.contains(accountEmailError) == true)
            ) {
                var email = emailValue.value.text
                if (email.isEmpty()) email = emailValueString.value
                showAuthorizationDialog(email, passwordValue.value)
            }

            val isPasswordError = errorText?.contains(accountPasswordError) ?: false
            val isFullEmailError =
                isEmailError || errorText?.contains(accountEmailError) == true
            val isDisplayNameError = !isPasswordError && !isFullEmailError && !isBirthdayError

            showErrorStatus(
                true, errorText, isDisplayNameError, isPasswordError, isFullEmailError,
                isBirthdayError
            )
        }
    }

    private fun showErrorStatus(
        isError: Boolean = false, error: String? = "", isDisplayNameError: Boolean = false,
        isPasswordError: Boolean = false, isEmailError: Boolean = false,
        isBirthdayError: Boolean = false
    ) {
        viewModelScope.launch(Dispatchers.Main) {
            if (!isError) {
                nicknameError.value = ""
                passwordError.value = ""
                emailError.value = ""
                birthdayError.value = ""
            } else {
                if (isPasswordError) setPasswordErrorText(
                    error, ResManager.getString(Res.string.error_message_sign_password_at_least),
                    accountWrongPasswordError = ResManager.getString(Res.string.auth_sign_in_wrong_password),
                    accountPasswordMinSizeError = ResManager.getString(Res.string.auth_sign_in_wrong_password_min_size)
                )
                if (isDisplayNameError) setDisplayNameErrorText(error)
                if (isEmailError) setEmailErrorText(
                    error ?: ResManager.getString(Res.string.auth_sign_in_incorrect_email)
                )
                if (isBirthdayError) setBirthdayErrorText(ResManager.getString(Res.string.pick_date_age_less_18_text))
            }
        }
    }


    fun hideError(errorField: ErrorField = ErrorField.All) {

        when (errorField) {
            ErrorField.All -> {
                nicknameError.value = ""
                passwordError.value = ""
                emailError.value = ""
                birthdayError.value = ""
            }

            ErrorField.DisplayName -> nicknameError.value = ""
            ErrorField.Password -> passwordError.value = ""
            ErrorField.Email -> emailError.value = ""
            ErrorField.Birthday -> birthdayError.value = ""
        }
    }


    private fun showAuthorizationDialog(email: String, password: String) {
        viewModelScope.launch(Dispatchers.Main) {
            val title = ResManager.getString(Res.string.error_message_warning_title)
            val text = ResManager.getString(Res.string.dialog_splash_sign_up_authorization_text)

            dialogManager.showMessageDialog(
                EDialogType.DIALOG_SIGN_IN_REGISTRATION,
                title = title, dialogText = text,
                callback = {
                    val event = SplashSignUpAboutEvent.SplashSignInEmail(
                        AuthorizationType.EMAIL, password, email
                    )
                    obtainEvent(event)
                }
            )
        }
    }

    fun onSignInClick() {
        if (AppVariant.isDebug()) {
            var email = emailValue.value.text
            if (email.isEmpty()) email = emailValueString.value
            val password = passwordValue.value
            val event = SplashSignUpAboutEvent.SplashSignInEmail(
                AuthorizationType.EMAIL, password, email
            )
            obtainEvent(event)
            return
        }
        val webBrowserManager by di.instance<WebBrowserManager>()
        webBrowserManager.showWebPage(Endpoint.getStoreUrl())
    }

    private fun setPasswordErrorText(
        error: String?, accountEmailError: String,
        accountWrongPasswordError: String,
        accountPasswordMinSizeError: String
    ) {
        if (error?.contains(accountEmailError) == true) {
            passwordError.value = accountPasswordMinSizeError
        } else passwordError.value = accountWrongPasswordError
    }

    private fun setDisplayNameErrorText(error: String?) {
        viewModelScope.launch(Dispatchers.Main) {
            val latin =
                ResManager.getString(Res.string.auth_sign_in_incorrect_latin_display_name)
            if (error?.contains(latin) == true) nicknameError.value = latin
            else nicknameError.value =
                ResManager.getString(Res.string.auth_sign_in_incorrect_display_name)
        }
    }

    private fun setEmailErrorText(error: String) {
        emailError.value = error
    }

    private fun setBirthdayErrorText(error: String) {
        birthdayError.value = error
    }

    private fun sendEvent(email: String?) {
//        if (email.isNullOrEmpty()) AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.registrationEmailEmpty.name)
//        else AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.registrationEmailNotEmpty.name)

        if (checkedEmail.value) {
            amplitudeManager.sendEvent(
                AmplitudeEvent.OnboardingCreateProfileScreenNotificationAgree("yes")
            )

            AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.registrationEmailNotificationOn.name)
        } else {
            amplitudeManager.sendEvent(
                AmplitudeEvent.OnboardingCreateProfileScreenNotificationAgree("no")
            )

            AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.registrationEmailNotificationOff.name)
        }
    }

