    fun generatePassword(
        length: Int = 15,
        useDigits: Boolean = true,
        useSpecial: Boolean = false
    ): String {
        val letters = ('a'..'z') + ('A'..'Z')
        val digits = if (useDigits) ('0'..'9') else emptyList()
        val special = if (useSpecial) listOf('!', '@', '#', '$', '%', '&', '*') else emptyList()

        val pool = letters + digits + special

        return (1..length)
            .map { pool.random() }
            .joinToString("")
    }
