package ui.screens.profile.profileMultiSelect

import androidx.annotation.UiThread
import androidx.compose.runtime.mutableStateListOf
import androidx.compose.runtime.mutableStateOf
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import dependencies.RepositoriesProvider
import dependencies.di
import fiori.sharedmodule.generated.resources.Res
import fiori.sharedmodule.generated.resources.people_profile_edit_interests_text
import fiori.sharedmodule.generated.resources.people_profile_edit_music_text
import fiori.sharedmodule.generated.resources.people_profile_title_interests
import fiori.sharedmodule.generated.resources.people_profile_title_music
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotpref.eventBus.EventBusManager
import kotpref.eventBus.PeopleProfileAddInfoKMP
import kotpref.models.AppVariant
import kotpref.models.account.Account
import kotpref.models.account.enums.AccountInterests
import kotpref.models.account.enums.AccountMusic
import kotpref.models.account.enums.getString
import kotpref.models.typeConverter.multi.AccountInterestsConverter
import kotpref.models.typeConverter.multi.AccountMusicConverter
import kotpref.profile.ProfileData
import kotpref.profile.ProfileDataField
import kotpref.utils.IPlatformInfoManager
import managers.AmplitudeEvent
import managers.AmplitudeManager
import managers.IFirebaseManager
import org.kodein.di.instance
import ui.managers.OnBoardingUpdateAccountManager
import ui.managers.OnBoardingUpdateAccountManagerEvent
import ui.managers.profileData.ProfileDataManager
import ui.resources.ResManager
import ui.screens.onboarding.start.MultiSelectItem

sealed class ProfileMultiSelectEvent {
    data class LocationPermission(val onAccess: (Any?) -> Unit) : ProfileMultiSelectEvent()
    data object OnBoardingNextPage : ProfileMultiSelectEvent()
    data class LoadPeopleSuccess(val peopleList: MutableList<Account>) : ProfileMultiSelectEvent()
    data object Back : ProfileMultiSelectEvent()
}

class ProfileMultiSelectVM(
    private val useSelectData: Boolean,
    private val profileDataField: ProfileDataField,
    private val viewModelCallback: (ProfileMultiSelectEvent) -> Unit,
) : ViewModel() {
    private var profileData: ProfileData? = null

    val repositoriesProvider by di.instance<RepositoriesProvider>()
    val firebaseManager by di.instance<IFirebaseManager>()
    private val deviceInfoManager by di.instance<IPlatformInfoManager>()
    private val amplitudeManager by di.instance<AmplitudeManager>()

    private val accountRepository = repositoriesProvider.accountRepository
    private val dialogManager = repositoriesProvider.dialogManager
    val userRegistered = accountRepository.getAppKeys().userRegistered

    val profileMultiSelectTitle = mutableStateOf("")
    val profileMultiSelectText = mutableStateOf("")
    val showingProgress = mutableStateOf(false)
    var profileMultiSelectList = mutableStateListOf<MultiSelectItem>()

    init {
        if (!userRegistered) {
            amplitudeManager.sendEvent(AmplitudeEvent.OnboardingInterestsScreenShown)
        }
        viewModelScope.launch(Dispatchers.Main) {

            fun setSelectData(list: List<String>?) {
                list?.forEach { item ->
                    val multiSelectItem = MultiSelectItem(itemTitle = item)
                    val index = profileMultiSelectList.indexOf(multiSelectItem)
                    profileMultiSelectList[index] = multiSelectItem.copy(onSelected = true)
                }
            }

            val myAccount = accountRepository.getMyAccount()
            val profileDataManager = ProfileDataManager()
            //profileDataManager.setAccount(myAccount)
            profileData = profileDataManager.getProfileData(profileDataField)
            val selectData = mutableListOf<String>()
            val isInterests = profileData?.profileDataField == ProfileDataField.Interests
            if (isInterests) {
                profileMultiSelectTitle.value =
                    ResManager.getString(Res.string.people_profile_title_interests)
                profileMultiSelectText.value =
                    ResManager.getString(Res.string.people_profile_edit_interests_text)
                val items = if (useSelectData) {
                    AccountInterestsConverter.stringToList(profileData?.selectData)
                } else {
                    AccountInterestsConverter.valuesToList(myAccount?.info?.interests)
                }
                items?.forEach { selectData.add(ResManager.getString(it.resId())) }
                AccountInterests.showingItems
                    .forEach { profileMultiSelectList.add(MultiSelectItem(ResManager.getString(it.resId()))) }
                setSelectData(selectData)
            } else {
                profileMultiSelectTitle.value =
                    ResManager.getString(Res.string.people_profile_title_music)
                profileMultiSelectText.value =
                    ResManager.getString(Res.string.people_profile_edit_music_text)
                val items = if (useSelectData) {
                    AccountMusicConverter.stringToList(profileData?.selectData)
                } else {
                    AccountMusicConverter.valuesToList(myAccount?.info?.music)
                }
                items?.forEach { selectData.add(ResManager.getString(it.resId())) }
                AccountMusic.entries
                    .forEach { profileMultiSelectList.add(MultiSelectItem(ResManager.getString(it.resId()))) }
                setSelectData(selectData)
            }
        }
    }

    fun setSelectItem(item: MultiSelectItem) {
        if (profileMultiSelectList.filter { it.onSelected }.size >= 10 && !item.onSelected) return

        val index = profileMultiSelectList.indexOf(item)
        profileMultiSelectList[index] = item.copy(onSelected = !item.onSelected)
//        alpha.value = if (multiSelectList.any { it.onSelected }) 1f else 0.3f
    }


    fun back() {
        viewModelCallback(ProfileMultiSelectEvent.Back)
    }

    @UiThread
    fun systemBack(): Boolean {
        if (!AppVariant.isParadiz() && showingProgress.value) return true
        if (userRegistered) return saveData()
        else {
            amplitudeManager.sendEvent(AmplitudeEvent.OnboardingBackButtonClicked("onboarding_interests_screen"))
            accountRepository.getAppKeys().onboardingCurrentPage--
        }
        //AnalyticsManager.onSendEvent(AnalyticsPeopleEvents.filterCloseClick.name)
        return false
    }

    fun clickedBtn(duplicate: Boolean) {
        showingProgress.value = true
        saveData()
    }

    private fun saveData(): Boolean {
        viewModelScope.launch {
            val selectItems = mutableListOf<String>()
            val result = mutableListOf<String>()

            val isInterests = profileData?.profileDataField == ProfileDataField.Interests
            if (isInterests) {
                profileMultiSelectList.filter { it.onSelected }.forEach {
                    val item = AccountInterests.showingItems.firstOrNull { enum ->
                        enum.resId().getString() == it.itemTitle
                    }
                    item?.let { enum -> selectItems.add(enum.resId().getString()) }
                }
                result.addAll(
                    AccountInterestsConverter.stringsToValues(selectItems) ?: mutableListOf()
                )
            } else {
                profileMultiSelectList.filter { it.onSelected }.forEach {
                    val item = AccountMusic.entries.firstOrNull { enum ->
                        enum.resId().getString() == it.itemTitle
                    }
                    item?.let { enum -> selectItems.add(enum.resId().getString()) }
                }
                result.addAll(AccountMusicConverter.stringsToValues(selectItems))
            }

            if (userRegistered) EventBusManager.post(
                PeopleProfileAddInfoKMP(profileData, result)
            ) else showNextPage(result)
        }
        return false
    }

    private fun showNextPage(result: MutableList<String>) {
        if (!userRegistered) {
            amplitudeManager.sendEvent(AmplitudeEvent.OnboardingInterestsScreenNextClicked(result.size))
        }
        viewModelScope.launch(Dispatchers.Main) { /* runBlocking */
            val account = accountRepository.myAccount ?: accountRepository.getMyAccount()
            account?.info?.interests = result
            accountRepository.saveAccount(account)
            OnBoardingUpdateAccountManager(routeTo = {
                when (it) {
                    is OnBoardingUpdateAccountManagerEvent.LoadPeopleSuccess -> {
                        viewModelCallback(ProfileMultiSelectEvent.LoadPeopleSuccess(it.peopleList))
                    }

                    is OnBoardingUpdateAccountManagerEvent.LocationPermission -> {
                        viewModelCallback(ProfileMultiSelectEvent.LocationPermission(it.onAccess))
                    }

                    OnBoardingUpdateAccountManagerEvent.ShowNextPage -> {
                        viewModelCallback(ProfileMultiSelectEvent.OnBoardingNextPage)
                    }
                }

            }, dialogManager, accountRepository) {
                showingProgress.value = false
            }.updateAccount(account, deviceInfoManager)
        }
    }
}