package ui.screens.onboarding.tutorial

import androidx.annotation.UiThread
import androidx.compose.runtime.mutableIntStateOf
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import dependencies.RepositoriesProvider
import dependencies.di
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotpref.models.AppVariant
import kotpref.models.account.enums.AccountIam
import kotpref.models.typeConverter.DateTimeConverter
import managers.AmplitudeEvent
import managers.AmplitudeManager
import managers.IBillingManager
import org.kodein.di.instance
import ui.components.EventVM
import ui.managers.AppsFlyerManagerData

sealed class OnBoardingTutorialEvent : EventVM {
    data class ShowMainPage(val clearBackStack: Boolean = false) : OnBoardingTutorialEvent()
    data object SubscribePropose : OnBoardingTutorialEvent()
    data object OnBoardingNextPage : OnBoardingTutorialEvent()
    data object Back : OnBoardingTutorialEvent()
}

class OnBoardingTutorialVM(
    private val fromFinishPage: Boolean,
    private val viewModelCallback: (OnBoardingTutorialEvent) -> Unit
) : ViewModel() {

    val repositoriesProvider by di.instance<RepositoriesProvider>()
    val billingManager by di.instance<IBillingManager>()
    val amplitudeManager by di.instance<AmplitudeManager>()
    private val accountRepository = repositoriesProvider.accountRepository

    val currentQuestion = mutableIntStateOf(0)
    private var pagesSize = 3

    init {
        if (AppVariant.isWeb()) billingManager.getAllProductDetails {}
    }

    fun clickedBtn() {
        if (currentQuestion.intValue + 1 >= pagesSize) {
            amplitudeManager.sendEvent(AmplitudeEvent.OnboardingTutorialScreen3ContinueClicked)

            val shortOnboarding = accountRepository.isShortOnboardingFlow()
            if (fromFinishPage && !shortOnboarding) {
                if (AppsFlyerManagerData.needShowVoucherPage) {
                    accountRepository.getAppKeys().userRegistered = true
                    viewModelCallback(OnBoardingTutorialEvent.ShowMainPage(true))
                } else showProposePageIfNeed()
            } else {
                val subsType = accountRepository.myAccount?.subscriptionStatus?.subscription?.type ?: 0
                if (subsType != 0) {
                    viewModelCallback(OnBoardingTutorialEvent.ShowMainPage())
                    return
                }
                viewModelCallback(OnBoardingTutorialEvent.OnBoardingNextPage)
            }
        } else {
            if (currentQuestion.intValue == 0) {
                amplitudeManager.sendEvent(AmplitudeEvent.OnboardingTutorialScreen1ContinueClicked)
            } else if (currentQuestion.intValue == 1) {
                amplitudeManager.sendEvent(AmplitudeEvent.OnboardingTutorialScreen2ContinueClicked)
            }
            currentQuestion.intValue++
        }
    }

    private fun showProposePageIfNeed() {
        val subsType = accountRepository.myAccount?.subscriptionStatus?.subscription?.type ?: 0
        if (subsType != 0) {
            viewModelCallback(OnBoardingTutorialEvent.ShowMainPage())
            return
        }
        billingManager.getPurchaseDetails(callback = {
            viewModelScope.launch(Dispatchers.Main) { /* runBlocking */
                val productId = billingManager.getProductId(it) ?: ""
                val paywallType = accountRepository.settingsPaywallType()
                val paywallStyle =
                    accountRepository.userAdaptyPaywalls.adaptyPaywallConfig?.getPaywallStyle() ?: 1
                val myGender = accountRepository.getMyAccount()?.info?.iamList?.firstOrNull()
                if (paywallType == 0 || productId.isNotEmpty() || (paywallType in 13..14 && myGender == AccountIam.W.position) || paywallStyle == 0) {
                    viewModelCallback(OnBoardingTutorialEvent.ShowMainPage())
                } else if (paywallType == 3 || paywallType == 6 || paywallType == 8) {
                    val boughtTrial = billingManager.usedFreeTrial()
                    if (boughtTrial) {
                        viewModelCallback(OnBoardingTutorialEvent.ShowMainPage())
                    } else {
                        viewModelCallback(OnBoardingTutorialEvent.SubscribePropose)
                    }
                } else {
                    viewModelCallback(OnBoardingTutorialEvent.SubscribePropose)
                }
            }
        })
    }

    private var lastClick = 0L

    private fun onBackClick() {
        if (currentQuestion.intValue == 0) {
            //router.route(Destination.Back())
            viewModelCallback(OnBoardingTutorialEvent.Back)
        } else currentQuestion.intValue--
    }

    @UiThread
    fun backSystem(): Boolean {
        val currentTime = DateTimeConverter.currentTimeMillis()
        if (currentTime - lastClick < 200) return true
        lastClick = currentTime

        return when {
            currentQuestion.intValue != 0 -> {
                if (currentQuestion.intValue == 2) {
                    amplitudeManager.sendEvent(AmplitudeEvent.OnboardingBackButtonClicked("onboarding_tutorial_screen_3"))
                } else if (currentQuestion.intValue == 1) {
                    amplitudeManager.sendEvent(AmplitudeEvent.OnboardingBackButtonClicked("onboarding_tutorial_screen_2"))
                }
                onBackClick()
                true
            }

            else -> {
                amplitudeManager.sendEvent(AmplitudeEvent.OnboardingBackButtonClicked("onboarding_tutorial_screen_1"))
                viewModelCallback(OnBoardingTutorialEvent.Back)
                /*if (!fromFinishPage) {
                    if (accountRepository.getAppKeys().onboardingWithSubscription) {
                        accountRepository.getAppKeys().onboardingCurrentPage--
                    } else {
                        accountRepository.getAppKeys().onboardingCurrentPage -= 2
                    }
                }*/
                false
            }
        }
    }
}